import subprocess, os, sys
def run(args, inp="", env=None, exe="./executable"):
    e={k:v for k,v in os.environ.items() if not k.startswith("FZF_")}
    if env:
        for k,v in env.items():
            if v is None:
                e.pop(k,None)
            else:
                e[k]=v
    p=subprocess.run([exe]+args, input=inp.encode() if isinstance(inp,str) else inp, capture_output=True, env=e)
    return p.stdout, p.stderr, p.returncode
def filt(query, items, extra=[], exe="./executable"):
    inp="\n".join(items)+("\n" if items else "")
    o,e,c=run(["--filter="+query]+extra, inp, exe=exe)
    return o.decode().splitlines(), c, e.decode()
