package main

import (
	"strings"
	"unicode"
)

// Scoring constants
const (
	scoreMatch        = 16
	scoreGapStart     = -3
	scoreGapExtension = -1
	bonusConsecutive  = 4
	bonusFirstCharMultiplier = 2
)

type schemeInfo struct {
	name string
	bonusWhite int
	bonusDelimiter int
	bonusNonWord int
	bonusCamel int
	delimiterSet map[rune]bool
	tiebreak []string // default tiebreak for scheme (applied when scheme option parsed)
}

func getScheme(name string) schemeInfo {
	switch strings.ToLower(name) {
	case "path":
		return schemeInfo{name: "path", bonusWhite: 8, bonusDelimiter: 9, bonusNonWord: 8, bonusCamel: 7, delimiterSet: map[rune]bool{'/': true}, tiebreak: []string{"pathname", "length"}}
	case "history":
		return schemeInfo{name: "history", bonusWhite: 8, bonusDelimiter: 8, bonusNonWord: 8, bonusCamel: 7, delimiterSet: map[rune]bool{'/': true, ',': true, ':': true, ';': true, '|': true}, tiebreak: []string{"index"}}
	default:
		return schemeInfo{name: "default", bonusWhite: 10, bonusDelimiter: 9, bonusNonWord: 8, bonusCamel: 7, delimiterSet: map[rune]bool{'/': true, ',': true, ':': true, ';': true, '|': true}, tiebreak: []string{"length"}}
	}
}

var genericDelimiterSet = map[rune]bool{'/': true, ',': true, ':': true, ';': true, '|': true}

type charClass int

const (
	classLower charClass = iota
	classUpper
	classLetter
	classNumber
	classWhite
	classDelimiter // scheme delimiter
	classNonWord
)

func classOf(r rune, sch schemeInfo) charClass {
	if unicode.IsLower(r) {
		return classLower
	}
	if unicode.IsUpper(r) {
		return classUpper
	}
	if unicode.IsLetter(r) {
		return classLetter
	}
	if unicode.IsDigit(r) {
		return classNumber
	}
	if r == ' ' || r == '\t' || unicode.IsSpace(r) {
		return classWhite
	}
	if sch.delimiterSet[r] {
		return classDelimiter
	}
	return classNonWord
}

func isWordRune(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsDigit(r)
}

// bonusAt computes bonus for a character at position i in text given scheme.
func computeBonuses(text []rune, sch schemeInfo) []int {
	bonuses := make([]int, len(text))
	prevClass := classWhite
	for i, r := range text {
		bonuses[i] = bonusFor(prevClass, r, sch)
		prevClass = classOf(r, sch)
	}
	return bonuses
}

func bonusFor(prevClass charClass, r rune, sch schemeInfo) int {
	cls := classOf(r, sch)
	if isWordRune(r) {
		switch prevClass {
		case classWhite:
			return sch.bonusWhite
		case classDelimiter:
			return sch.bonusDelimiter
		case classNonWord:
			return sch.bonusNonWord
		}
		// camel transitions when prev is word
		if prevClass == classLower && cls == classUpper {
			return sch.bonusCamel
		}
		if cls == classNumber && prevClass != classNumber {
			// prev is word here (lower/upper/letter)
			if prevClass == classLower || prevClass == classUpper || prevClass == classLetter {
				return sch.bonusCamel
			}
		}
		return 0
	}
	if genericDelimiterSet[r] {
		switch prevClass {
		case classWhite:
			return sch.bonusWhite
		case classDelimiter:
			return sch.bonusDelimiter
		}
		return 0
	}
	return 0
}

// Term types
type termType int

const (
	termFuzzy termType = iota
	termExact
	termPrefix
	termSuffix
	termEqual
	termBoundary
)

type term struct {
	typ termType
	inv bool
	text []rune
	caseSensitive bool
	dropped bool
}

type pattern struct {
	termSets [][]term
	hasPositive bool
	empty bool
	// config
	sch schemeInfo
	algo string
	exactGlobal bool
	extended bool
	caseMode int // 0 smart, 1 ignore, 2 respect
	literal bool
}

const (
	caseSmart = iota
	caseIgnore
	caseRespect
)

func containsUpper(rs []rune) bool {
	for _, r := range rs {
		if unicode.IsUpper(r) {
			return true
		}
	}
	return false
}

func (p *pattern) termCaseSensitive(text []rune) bool {
	switch p.caseMode {
	case caseIgnore:
		return false
	case caseRespect:
		return true
	default:
		return containsUpper(text)
	}
}

// tokenizeExtended splits query by unescaped spaces
func tokenizeExtended(query string) []string {
	var tokens []string
	var cur []rune
	has := false
	rs := []rune(query)
	for i := 0; i < len(rs); i++ {
		r := rs[i]
		if r == '\\' && i+1 < len(rs) && rs[i+1] == ' ' {
			cur = append(cur, ' ')
			has = true
			i++
			continue
		}
		if r == ' ' {
			if has || len(cur) > 0 {
				tokens = append(tokens, string(cur))
				cur = nil
				has = false
			}
			continue
		}
		cur = append(cur, r)
		has = true
	}
	if has || len(cur) > 0 {
		tokens = append(tokens, string(cur))
	}
	return tokens
}

func buildPattern(query string, opts *Options) *pattern {
	sch := getScheme(opts.Scheme)
	p := &pattern{
		sch: sch,
		algo: opts.Algo,
		exactGlobal: opts.Exact,
		extended: opts.Extended,
		literal: opts.Literal,
	}
	switch opts.CaseMode {
	case "ignore":
		p.caseMode = caseIgnore
	case "respect":
		p.caseMode = caseRespect
	default:
		p.caseMode = caseSmart
	}
	if !opts.Extended {
		if query == "" {
			p.empty = true
			return p
		}
		text := []rune(query)
		typ := termFuzzy
		if opts.Exact {
			typ = termExact
		}
		t := term{typ: typ, text: text, caseSensitive: p.termCaseSensitive(text)}
		p.termSets = [][]term{{t}}
		p.hasPositive = true
		return p
	}
	// extended
	tokens := tokenizeExtended(query)
	var sets [][]term
	afterBar := false
	for _, rawTok := range tokens {
		tok := strings.ReplaceAll(rawTok, "\t", " ")
		if tok == "|" {
			if len(sets) > 0 && !afterBar {
				afterBar = true
				continue
			}
			// fall through as term
		}
		t := p.parseTerm(tok)
		if t.dropped {
			// dropped terms do not create a set; but if afterBar, keep afterBar? Keep state as is
			// If token was after bar and dropped, the pending OR is still? Reset to false to behave reasonably
			// Actually dropped token should not break grouping; leave afterBar unchanged
			continue
		}
		if !t.inv {
			p.hasPositive = true
		}
		if afterBar && len(sets) > 0 {
			sets[len(sets)-1] = append(sets[len(sets)-1], t)
			afterBar = false
		} else {
			// If afterBar but no sets (should not happen since dropped check), create new
			sets = append(sets, []term{t})
			afterBar = false
		}
	}
	p.termSets = sets
	if len(sets) == 0 {
		p.empty = true
	}
	return p
}

func (p *pattern) parseTerm(tokStr string) term {
	s := tokStr
	inv := false
	if len(s) > 0 && s[0] == '!' {
		if len(s) == 1 {
			return term{dropped: true}
		}
		inv = true
		s = s[1:]
	}
	rs := []rune(s)
	// Quote handling
	if len(rs) > 0 && rs[0] == '\'' {
		if len(rs) > 2 && rs[len(rs)-1] == '\'' {
			text := rs[1 : len(rs)-1]
			return term{typ: termBoundary, inv: inv, text: text, caseSensitive: p.termCaseSensitive(text)}
		}
		text := rs[1:]
		typ := termExact
		if p.exactGlobal && !inv {
			typ = termFuzzy
		} else if p.exactGlobal && inv {
			// In exact mode, !'foo' : inner quoted becomes fuzzy but inverted?
			// Observed !'foo in exact works as inverse fuzzy
			typ = termFuzzy
			// But if inv and exact global, the base inverted term's quoted handling: quoting flips
			// We'll keep fuzzy
			if !p.exactGlobal {
				typ = termExact
			}
		}
		if len(text) == 0 {
			return term{dropped: true}
		}
		return term{typ: typ, inv: inv, text: text, caseSensitive: p.termCaseSensitive(text)}
	}
	// base type
	var typ termType
	if inv || p.exactGlobal {
		typ = termExact
	} else {
		typ = termFuzzy
	}
	// suffix check first (on original rs length >1)
	suffixed := false
	if len(rs) > 1 && rs[len(rs)-1] == '$' {
		suffixed = true
		rs = rs[:len(rs)-1]
		typ = termSuffix
	}
	if len(rs) > 0 && rs[0] == '^' {
		if suffixed {
			typ = termEqual
		} else {
			typ = termPrefix
		}
		rs = rs[1:]
	} else if suffixed {
		typ = termSuffix
	}
	if len(rs) == 0 {
		return term{dropped: true}
	}
	return term{typ: typ, inv: inv, text: rs, caseSensitive: p.termCaseSensitive(rs)}
}

// scoring alignment for a given set of matched positions
func scoreAlignment(positions []int, bonuses []int) int {
	total := 0
	prevPos := -1
	effPrev := 0
	for idx, pos := range positions {
		b := bonuses[pos]
		if idx == 0 {
			total += scoreMatch + b*bonusFirstCharMultiplier
			effPrev = b
		} else if pos == prevPos+1 {
			eff := b
			if bonusConsecutive > eff {
				eff = bonusConsecutive
			}
			if effPrev > eff {
				eff = effPrev
			}
			total += scoreMatch + eff
			effPrev = eff
		} else {
			gap := pos - prevPos - 1
			total += scoreMatch + b + scoreGapStart + (gap-1)*scoreGapExtension
			effPrev = b
		}
		prevPos = pos
	}
	return total
}

// term core match: returns ok, score, begin, end (rune offsets)
func (p *pattern) matchTerm(t term, text []rune, bonuses []int) (bool, int, int, int) {
	if len(t.text) == 0 {
		return true, 0, 0, 0
	}
	switch t.typ {
	case termFuzzy:
		if p.algo == "v1" {
			return p.fuzzyV1(t, text, bonuses)
		}
		return p.fuzzyV2(t, text, bonuses)
	case termExact:
		return p.exactMatch(t, text, bonuses, -1, -1) // any
	case termPrefix:
		// must match at 0
		if len(text) < len(t.text) {
			return false, 0, 0, 0
		}
		for i, pr := range t.text {
			if !charEqual(pr, text[i], t.caseSensitive, p.literal) {
				return false, 0, 0, 0
			}
		}
		positions := make([]int, len(t.text))
		for i := range positions { positions[i] = i }
		return true, scoreAlignment(positions, bonuses), 0, len(t.text)
	case termSuffix:
		if len(text) < len(t.text) {
			return false, 0, 0, 0
		}
		start := len(text) - len(t.text)
		for i, pr := range t.text {
			if !charEqual(pr, text[start+i], t.caseSensitive, p.literal) {
				return false, 0, 0, 0
			}
		}
		positions := make([]int, len(t.text))
		for i := range positions { positions[i] = start + i }
		return true, scoreAlignment(positions, bonuses), start, len(text)
	case termEqual:
		if len(text) != len(t.text) {
			return false, 0, 0, 0
		}
		for i, pr := range t.text {
			if !charEqual(pr, text[i], t.caseSensitive, p.literal) {
				return false, 0, 0, 0
			}
		}
		positions := make([]int, len(t.text))
		for i := range positions { positions[i] = i }
		return true, scoreAlignment(positions, bonuses), 0, len(text)
	case termBoundary:
		return p.boundaryMatch(t, text, bonuses)
	}
	return false, 0, 0, 0
}

func (p *pattern) exactMatch(t term, text []rune, bonuses []int, _ int, _ int) (bool, int, int, int) {
	m := len(t.text)
	n := len(text)
	if m == 0 {
		return true, 0, 0, 0
	}
	if m > n {
		return false, 0, 0, 0
	}
	bestScore := -1 << 30
	bestStart := -1
	for s := 0; s+ m <= n; s++ {
		ok := true
		for i := 0; i < m; i++ {
			if !charEqual(t.text[i], text[s+i], t.caseSensitive, p.literal) {
				ok = false
				break
			}
		}
		if !ok {
			continue
		}
		positions := make([]int, m)
		for i := range positions { positions[i] = s+i }
		sc := scoreAlignment(positions, bonuses)
		if sc > bestScore {
			bestScore = sc
			bestStart = s
		}
	}
	if bestStart < 0 {
		return false, 0, 0, 0
	}
	return true, bestScore, bestStart, bestStart + m
}

type neighborCat int
const (
	catW neighborCat = iota
	catD
	catN
	catU
	catWord
)

func neighborCategory(text []rune, idx int) neighborCat {
	// idx is position of neighbor char, or -1 for before start, len for after end
	if idx < 0 || idx >= len(text) {
		return catW
	}
	r := text[idx]
	if r == '_' {
		return catU
	}
	if r == ' ' || r == '\t' || unicode.IsSpace(r) {
		return catW
	}
	if genericDelimiterSet[r] {
		return catD
	}
	if isWordRune(r) {
		return catWord
	}
	return catN
}

func (p *pattern) boundaryMatch(t term, text []rune, bonuses []int) (bool, int, int, int) {
	m := len(t.text)
	n := len(text)
	if m > n {
		return false, 0, 0, 0
	}
	bestScore := -1 << 30
	bestStart := -1
	for s := 0; s+m <= n; s++ {
		ok := true
		for i := 0; i < m; i++ {
			if !charEqual(t.text[i], text[s+i], t.caseSensitive, p.literal) {
				ok = false
				break
			}
		}
		if !ok {
			continue
		}
		pre := neighborCategory(text, s-1)
		post := neighborCategory(text, s+m)
		if pre == catWord || post == catWord {
			continue
		}
		var val int
		if post == catU {
			if pre == catU {
				val = 5
			} else {
				val = 7
			}
		} else {
			switch pre {
			case catW:
				val = p.sch.bonusWhite
			case catD:
				val = p.sch.bonusDelimiter
			case catN:
				val = p.sch.bonusNonWord
			case catU:
				val = 6 // special underscored pre: bonusNonWord-2 in default (8->6); assume constant 6
				// For schemes where bonusNonWord differs, this remains 6? History/path also 8 -> 6
			}
		}
		sc := scoreMatch*m + val
		if sc > bestScore {
			bestScore = sc
			bestStart = s
		}
	}
	if bestStart < 0 {
		return false, 0, 0, 0
	}
	return true, bestScore, bestStart, bestStart + m
}

func (p *pattern) fuzzyForwardBackward(t term, text []rune) (int, int, []int, bool) {
	// forward
	m := len(t.text)
	n := len(text)
	j := 0
	end := -1
	for i := 0; i < n && j < m; i++ {
		if charEqual(t.text[j], text[i], t.caseSensitive, p.literal) {
			j++
			if j == m {
				end = i + 1
				break
			}
		}
	}
	if j < m {
		return 0, 0, nil, false
	}
	// backward
	positions := make([]int, m)
	j = m - 1
	begin := -1
	for i := end - 1; i >= 0 && j >= 0; i-- {
		if charEqual(t.text[j], text[i], t.caseSensitive, p.literal) {
			positions[j] = i
			j--
			if j < 0 {
				begin = i
				break
			}
		}
	}
	if begin < 0 {
		return 0, 0, nil, false
	}
	return begin, end, positions, true
}

func (p *pattern) fuzzyV1(t term, text []rune, bonuses []int) (bool, int, int, int) {
	_, _, positions, ok := p.fuzzyForwardBackward(t, text)
	if !ok {
		return false, 0, 0, 0
	}
	sc := scoreAlignment(positions, bonuses)
	return true, sc, positions[0], positions[len(positions)-1] + 1
}

func (p *pattern) fuzzyV2(t term, text []rune, bonuses []int) (bool, int, int, int) {
	m := len(t.text)
	begin, end, _, ok := p.fuzzyForwardBackward(t, text)
	if !ok {
		return false, 0, 0, 0
	}
	W := end - begin
	if W <= 0 {
		return false, 0, 0, 0
	}
	// eff values possible
	effVals := []int{0, bonusConsecutive, p.sch.bonusCamel, p.sch.bonusNonWord, p.sch.bonusDelimiter, p.sch.bonusWhite}
	// dedup / sort retain
	// Map eff -> index
	effIndex := make(map[int]int)
	var effList []int
	for _, v := range effVals {
		if _, exists := effIndex[v]; !exists {
			effIndex[v] = len(effList)
			effList = append(effList, v)
		}
	}
	E := len(effList)
	const negInf = -1 << 29
	// DP[j][i][e]
	// Use 3D slices
	score := make([][][]int, m)
	prevPosArr := make([][][]int, m) // predecessor window index, -1 start
	prevEffArr := make([][][]int, m)
	for j := 0; j < m; j++ {
		score[j] = make([][]int, W)
		prevPosArr[j] = make([][]int, W)
		prevEffArr[j] = make([][]int, W)
		for i := 0; i < W; i++ {
			score[j][i] = make([]int, E)
			prevPosArr[j][i] = make([]int, E)
			prevEffArr[j][i] = make([]int, E)
			for e := 0; e < E; e++ {
				score[j][i][e] = negInf
				prevPosArr[j][i][e] = -2
				prevEffArr[j][i][e] = -1
			}
		}
	}
	// For computing gap transitions, we need best over eff for each (j,i) as we go.
	for i := 0; i < W; i++ {
		gi := begin + i
		if !charEqual(t.text[0], text[gi], t.caseSensitive, p.literal) {
			continue
		}
		b := bonuses[gi]
		ei, ok := effIndex[b]
		if !ok { continue }
		sc := scoreMatch + b*bonusFirstCharMultiplier
		if sc > score[0][i][ei] {
			score[0][i][ei] = sc
			prevPosArr[0][i][ei] = -1
		}
	}
	// helper to get best score/eff for a level at position
	bestAt := func(j, i int) (int, int) {
		best := negInf
		bestE := -1
		for e := 0; e < E; e++ {
			if score[j][i][e] > best {
				best = score[j][i][e]
				bestE = e
			}
		}
		return best, bestE
	}
	for j := 1; j < m; j++ {
		// precompute prefix maximum of (bestPrev[p] + p) for gap transitions
		// prefixBestVal[p] = max_{pp<=p} (bestAt(j-1,pp)+pp) and arg
		type prefInfo struct { val int; pos int; eff int }
		prefs := make([]prefInfo, W)
		curBest := negInf
		curPos := -1
		curEff := -1
		for i := 0; i < W; i++ {
			bs, be := bestAt(j-1, i)
			if be >= 0 {
				val := bs + i
				if val > curBest {
					curBest = val
					curPos = i
					curEff = be
				}
			}
			prefs[i] = prefInfo{val: curBest, pos: curPos, eff: curEff}
		}
		for i := 0; i < W; i++ {
			gi := begin + i
			if !charEqual(t.text[j], text[gi], t.caseSensitive, p.literal) {
				continue
			}
			b := bonuses[gi]
			ei := effIndex[b]
			// gap transition: p <= i-2
			if i >= 2 || (i >= 1) {
				// need p up to i-2
				if i-2 >= 0 {
					pref := prefs[i-2]
					if pref.pos >= 0 {
						cand := pref.val + (-1 - i) + scoreMatch + b // see derivation: gap penalty contribution = -1 -i + p
						// Wait score: prevScore + 16 + b + gapPenalty, gapPenalty = -3-(gap-1), gap=i-p-1 => -3-(i-p-2)=-1-i+p
						// cand = (prevScore + p) + (-1-i)+16+b = pref.val + (-1-i)+16+b
						cand = pref.val + (-1 - i) + scoreMatch + b
						if cand > score[j][i][ei] {
							score[j][i][ei] = cand
							prevPosArr[j][i][ei] = pref.pos
							prevEffArr[j][i][ei] = pref.eff
						}
					}
				} else if i == 1 {
					// gap cannot be <1 if p=0 and i=1 is consecutive, handled below
				}
			}
			// consecutive transition
			if i > 0 {
				for ePrev := 0; ePrev < E; ePrev++ {
					prevScore := score[j-1][i-1][ePrev]
					if prevScore == negInf {
						continue
					}
					effPrev := effList[ePrev]
					effNew := b
					if bonusConsecutive > effNew { effNew = bonusConsecutive }
					if effPrev > effNew { effNew = effPrev }
					eiNew, ok := effIndex[effNew]
					if !ok { continue }
					cand := prevScore + scoreMatch + effNew
					if cand > score[j][i][eiNew] {
						score[j][i][eiNew] = cand
						prevPosArr[j][i][eiNew] = i - 1
						prevEffArr[j][i][eiNew] = ePrev
					}
				}
			}
		}
	}
	// find best final
	bestScore := negInf
	bestI := -1
	bestE := -1
	for i := 0; i < W; i++ {
		for e := 0; e < E; e++ {
			sc := score[m-1][i][e]
			if sc > bestScore {
				bestScore = sc
				bestI = i
				bestE = e
			}
		}
	}
	if bestI < 0 {
		return false, 0, 0, 0
	}
	// backtrack
	positions := make([]int, m)
	j := m - 1
	i := bestI
	e := bestE
	for j >= 0 {
		positions[j] = begin + i
		if j == 0 {
			break
		}
		pi := prevPosArr[j][i][e]
		pe := prevEffArr[j][i][e]
		if pi < 0 {
			// Should not happen for valid alignment; fail back to backward positions
			break
		}
		i = pi
		e = pe
		j--
	}
	return true, bestScore, positions[0], positions[m-1] + 1
}

// Match against search text: returns matched, score, begin, end offsets (rune indices)
func (p *pattern) match(text []rune) (bool, int, int, int) {
	if p.empty || len(p.termSets) == 0 {
		return true, 0, 0, 0
	}
	bonuses := computeBonuses(text, p.sch)
	total := 0
	overallBegin := -1
	overallEnd := -1
	for _, set := range p.termSets {
		bestScore := -1 << 30
		bestBegin := -1
		bestEnd := -1
		matched := false
		for _, t := range set {
			if t.inv {
				ok, _, _, _ := p.matchTerm(t.asNonInv(), text, bonuses)
				if !ok {
					// inverse candidate score 0
					if 0 > bestScore || !matched {
						// Inverse candidate only if no positive candidate with score >=0? Actually max among candidates: score 0 could be less than a positive term's score but its existence counts.
						// We choose best score; if positive candidate has negative... scores are positive normally.
						// Keep inverse as candidate with score 0 if it is greater than current best.
						if !matched || 0 > bestScore {
							bestScore = 0
							bestBegin = -1
							bestEnd = -1
						}
						matched = true
					}
				}
				continue
			}
			ok, sc, b, e := p.matchTerm(t, text, bonuses)
			if !ok {
				continue
			}
			if !matched || sc > bestScore {
				bestScore = sc
				bestBegin = b
				bestEnd = e
				matched = true
			}
		}
		if !matched {
			return false, 0, 0, 0
		}
		total += bestScore
		if overallBegin == -1 && bestBegin != -1 {
			overallBegin = bestBegin
			overallEnd = bestEnd
		}
	}
	if overallBegin == -1 {
		overallBegin = 0
		overallEnd = 0
	}
	return true, total, overallBegin, overallEnd
}

func (t term) asNonInv() term {
	t2 := t
	t2.inv = false
	return t2
}

