// splitOptsString parses an env/file opts string into argument tokens
func splitOptsString(s string) ([]string, error) {
	var tokens []string
	// Process line by line for comment/operator handling but keep quoted newlines? Simplify: scanner over whole string.
	i := 0
	n := len(s)
	var cur strings.Builder
	hasToken := false
	inSingle := false
	inDouble := false
	skipToNextLine := false
	for i < n {
		c := s[i]
		if skipToNextLine {
			if c == '\n' {
				skipToNextLine = false
			}
			i++
			continue
		}
		if inSingle {
			if c == '\'' {
				inSingle = false
			} else {
				cur.WriteByte(c)
			}
			i++
			continue
		}
		if inDouble {
			if c == '"' {
				inDouble = false
				i++
				continue
			}
			if c == '\\' && i+1 < n {
				next := s[i+1]
				if next == '"' || next == '\\' || next == '$' || next == '`' || next == '\n' {
					if next != '\n' {
						cur.WriteByte(next)
					}
					i += 2
					continue
				}
				cur.WriteByte(c)
				i++
				continue
			}
			cur.WriteByte(c)
			i++
			continue
		}
		// not in quote
		if c == '\'' {
			inSingle = true
			hasToken = true
			i++
			continue
		}
		if c == '"' {
			inDouble = true
			hasToken = true
			i++
			continue
		}
		if c == '\\' {
			if i+1 >= n {
				return nil, fmt.Errorf("invalid command line string")
			}
			cur.WriteByte(s[i+1])
			hasToken = true
			i += 2
			continue
		}
		if c == '#' {
			if !hasToken {
				skipToNextLine = true
				continue
			}
			cur.WriteByte(c)
			i++
			continue
		}
		if c == ';' || c == '&' || c == '|' {
			if hasToken {
				tokens = append(tokens, cur.String())
				cur.Reset()
				hasToken = false
			}
			skipToNextLine = true
			continue
		}
		if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
			if hasToken {
				tokens = append(tokens, cur.String())
				cur.Reset()
				hasToken = false
			}
			i++
			continue
		}
		cur.WriteByte(c)
		hasToken = true
		i++
	}
	if inSingle || inDouble {
		return nil, fmt.Errorf("invalid command line string")
	}
	if hasToken {
		tokens = append(tokens, cur.String())
	}
	return tokens, nil
}

// parseOptions processes args with label; returns error (already labeled? We'll return raw msg and label handling at caller)
// To match error messages, we will return an error whose string is already appropriately prefixed by caller wrapper.
// This function returns raw message; caller wraps.
func (o *Options) parseArgs(args []string) error {
	i := 0
	for i < len(args) {
		arg := args[i]
		// '--' is ignored
		if arg == "--" {
			i++
			continue
		}
		// Short options handling
		if len(arg) >= 1 && arg[0] == '-' && len(arg) >= 2 && arg[1] != '-' {
			// single dash short
			handled, consumed, err := o.parseShort(arg, args, i)
			if err != nil {
				return err
			}
			if handled {
				i += consumed
				continue
			}
			// fallthrough to unknown
			return fmt.Errorf("unknown option: %s", arg)
		}
		if len(arg) >= 2 && arg[0] == '+' && arg[1] != 0 {
			handled, err := o.parsePlus(arg)
			if err != nil {
				return err
			}
			if handled {
				i++
				continue
			}
			return fmt.Errorf("unknown option: %s", arg)
		}
		if strings.HasPrefix(arg, "--") {
			consumed, err := o.parseLong(arg, args, i)
			if err != nil {
				return err
			}
			i += consumed
			continue
		}
		// positional
		return fmt.Errorf("unknown option: %s", arg)
	}
	return nil
}

func (o *Options) parsePlus(arg string) (bool, error) {
	switch arg {
	case "+x":
		o.Extended = false
	case "+i":
		o.CaseMode = "respect"
	case "+s":
		o.Sort = false
	case "+m":
		o.MultiSet = false
		o.Multi = 0
	case "+e":
		o.Exact = false
	case "+1":
		o.Select1 = false
	case "+0":
		o.Exit0 = false
	default:
		return false, nil
	}
	return true, nil
}

func (o *Options) parseShort(arg string, args []string, idx int) (bool, int, error) {
	// returns handled, tokens consumed, error
	switch arg {
	case "-e":
		o.Exact = true
		return true, 1, nil
	case "-x":
		o.Extended = true
		return true, 1, nil
	case "-i":
		o.CaseMode = "ignore"
		return true, 1, nil
	case "-s":
		o.Sort = true
		return true, 1, nil
	case "-m":
		o.MultiSet = true
		o.Multi = -1
		return true, 1, nil
	case "-1":
		o.Select1 = true
		return true, 1, nil
	case "-0":
		o.Exit0 = true
		return true, 1, nil
	case "-h":
		o.Mode = "help"
		return true, 1, nil
	}
	// prefix value options: -f, -q, -n, -d, -m, -s (with ignored suffix for -s)
	if len(arg) > 2 {
		switch arg[1] {
		case 'f':
			v := arg[2:]
			f := v
			o.Filter = &f
			return true, 1, nil
		case 'q':
			o.Query = arg[2:]
			return true, 1, nil
		case 'n':
			v := arg[2:]
			if err := o.setNth(v); err != nil { return true, 1, err }
			return true, 1, nil
		case 'd':
			v := arg[2:]
			if err := o.setDelimiter(v); err != nil { return true, 1, err }
			return true, 1, nil
		case 'm':
			v := arg[2:]
			n, err := parseIntStrict(v)
			if err != nil { return true, 1, fmt.Errorf("not a valid integer: %s", v) }
			o.MultiSet = true
			o.Multi = n
			return true, 1, nil
		case 's':
			// -s followed by anything: treat as enable sort (observed)
			o.Sort = true
			return true, 1, nil
		}
	}
	// Exact short needing value: -f, -q, -n, -d alone
	if len(arg) == 2 {
		switch arg[1] {
		case 'f':
			if idx+1 >= len(args) { return true, 1, fmt.Errorf("query string required") }
			v := args[idx+1]
			f := v
			o.Filter = &f
			return true, 2, nil
		case 'q':
			if idx+1 >= len(args) { return true, 1, fmt.Errorf("query string required") }
			o.Query = args[idx+1]
			return true, 2, nil
		case 'n':
			if idx+1 >= len(args) { return true, 1, fmt.Errorf("nth expression required") }
			if err := o.setNth(args[idx+1]); err != nil { return true, 1, err }
			return true, 2, nil
		case 'd':
			if idx+1 >= len(args) { return true, 1, fmt.Errorf("delimiter required") }
			if err := o.setDelimiter(args[idx+1]); err != nil { return true, 1, err }
			return true, 2, nil
		}
	}
	return false, 0, nil
}

// helpers

func parseIntStrict(v string) (int, error) {
	if v == "" {
		return 0, fmt.Errorf("empty")
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		return 0, err
	}
	return n, nil
}

func parseNonNegativeInt(v string, requiredMsg, mustMsg string) (int, error) {
	n, err := parseIntStrict(v)
	if err != nil {
		return 0, fmt.Errorf("%s", requiredMsg)
	}
	if n < 0 {
		if mustMsg != "" {
			return 0, fmt.Errorf("%s", mustMsg)
		}
		return 0, fmt.Errorf("%s", requiredMsg)
	}
	return n, nil
}

// setters

func (o *Options) setNth(v string) error {
	expr, err := parseFieldExpr(v)
	if err != nil {
		return err
	}
	o.NthExpr = expr
	o.HasNth = true
	// keep spec for transform use
	o.Nth = &nthSpec{expr: expr, raw: v}
	return nil
}
func (o *Options) setWithNth(v string) error {
	spec, err := parseNthSpecValidated(v)
	if err != nil {
		return err
	}
	o.WithNth = spec
	return nil
}
func (o *Options) setAcceptNth(v string) error {
	spec, err := parseNthSpecValidated(v)
	if err != nil {
		return err
	}
	o.AcceptNth = spec
	return nil
}
func (o *Options) setDelimiter(v string) error {
	// validate regex compiles (Go RE2 same as fzf)
	if v != "" {
		if _, err := regexp.Compile(v); err != nil {
			// fzf error message for invalid delimiter regex?
			return fmt.Errorf("%s", err.Error())
		}
	}
	s := v
	o.Delimiter = &s
	return nil
}
func (o *Options) setTiebreak(v string) error {
	if v == "" {
		return fmt.Errorf("invalid sort criterion: %s", v)
	}
	parts := strings.Split(v, ",")
	seen := map[string]bool{}
	for _, p := range parts {
		lp := strings.ToLower(p)
		switch lp {
		case "length", "chunk", "pathname", "begin", "end", "index":
		default:
			return fmt.Errorf("invalid sort criterion: %s", p)
		}
		if seen[lp] {
			return fmt.Errorf("duplicate sort criteria: %s", lp)
		}
		seen[lp] = true
	}
	// index must be last
	for i, p := range parts {
		if strings.ToLower(p) == "index" && i != len(parts)-1 {
			return fmt.Errorf("index should be the last criterion")
		}
	}
	var tb []string
	for _, p := range parts {
		tb = append(tb, strings.ToLower(p))
	}
	o.Tiebreak = tb
	return nil
}
func (o *Options) setScheme(v string) error {
	lv := strings.ToLower(v)
