func validateKeyName(name string) error {
	if name == "" {
		return fmt.Errorf("key name required")
	}
	lower := strings.ToLower(name)
	if eventNames[lower] {
		return nil
	}
	if simpleNamedKeys[lower] {
		return nil
	}
	// generated modifier combos
	bases := []string{"up", "down", "left", "right", "home", "end", "delete", "page-up", "page-down"}
	prefixes := []string{"ctrl-", "alt-", "shift-", "ctrl-alt-", "ctrl-shift-", "alt-shift-", "ctrl-alt-shift-", "shift-ctrl-", "shift-alt-", "shift-ctrl-alt-"}
	for _, pre := range prefixes {
		for _, b := range bases {
			if lower == pre+b {
				return nil
			}
		}
		// backspace variants with ctrl/alt combos
		if lower == pre+"backspace" || lower == pre+"bspace" || lower == pre+"bs" {
			if strings.Contains(pre, "ctrl") || strings.Contains(pre, "alt") {
				return nil
			}
		}
	}
	// ctrl-[a-z]
	if strings.HasPrefix(lower, "ctrl-") {
		rest := lower[5:]
		if utf8.RuneCountInString(rest) == 1 {
			r, _ := utf8.DecodeRuneInString(rest)
			if r >= 'a' && r <= 'z' {
				return nil
			}
		}
	}
	// ctrl-alt-[a-z]
	if strings.HasPrefix(lower, "ctrl-alt-") {
		rest := lower[9:]
		if utf8.RuneCountInString(rest) == 1 {
			r, _ := utf8.DecodeRuneInString(rest)
			if r >= 'a' && r <= 'z' {
				return nil
			}
		}
	}
	// alt-* single character (case-sensitive char, but prefix case-insensitive)
	// Find "alt-" in original ignoring case
	if len(name) >= 4 && strings.ToLower(name[:4]) == "alt-" {
		rest := name[4:]
		if utf8.RuneCountInString(rest) == 1 {
			return nil
		}
	}
	// any single character
	if utf8.RuneCountInString(name) == 1 {
		return nil
	}
	return fmt.Errorf("unsupported key: %s", name)
}

func isPrintableSingleKey(name string) bool {
	if utf8.RuneCountInString(name) != 1 {
		return false
	}
	r, _ := utf8.DecodeRuneInString(name)
	return r >= 0x20 && r != 0x7f
}

