// parseBindString parses a --bind value; appends to binds; returns error
func (o *Options) addBind(v string) error {
	if v == "" {
		return fmt.Errorf("key name required")
	}
	// We parse sequentially: pairs separated by commas at top level (outside brackets / colon-args)
	i := 0
	runes := []rune(v)
	n := len(runes)
	for i < n {
		// parse key list for this pair: read until ':' that separates keys from actions.
		// Keys are comma-separated themselves, but the colon after a key group marks start.
		// Strategy: Find separator colon. However a key can be ':' itself or '::' etc.
		// Special cases: if binding starts with ':' as key, the pair is "::action" or ":...??"
		// We'll implement scanning:
		// First, try to interpret first character ':' as a single-char key if the second char is also ':'
		startPair := i
		var keyStr string
		var actionStart int
		if runes[i] == ':' {
			// ':' key: need a second ':' as separator
			if i+1 < n && runes[i+1] == ':' {
				keyStr = ":"
				actionStart = i + 2
			} else {
				return fmt.Errorf("key name required")
			}
		} else {
			// find colon
			colonIdx := -1
			for j := i; j < n; j++ {
				if runes[j] == ':' {
					colonIdx = j
					break
				}
				if runes[j] == ',' {
					// comma before colon => this segment has no colon yet, continue scanning keys (keys are comma separated)
					continue
				}
			}
			if colonIdx == -1 {
				// No colon: the remaining string is a key segment with no action
				seg := string(runes[startPair:])
				return fmt.Errorf("bind action not specified: %s", seg)
			}
			keyStr = string(runes[startPair:colonIdx])
			actionStart = colonIdx + 1
		}
		if strings.TrimSpace(keyStr) == "" {
			return fmt.Errorf("key name required")
		}
		keys := strings.Split(keyStr, ",")
		for _, k := range keys {
			if k == "" {
				return fmt.Errorf("key name required")
			}
			if err := validateKeyName(k); err != nil {
				return err
			}
		}
		// Parse actions starting at actionStart. Actions are '+' separated, commas end pair unless inside argument.
		// We'll parse actions and also find end of this pair (index of top-level comma separating next pair or end)
		actions, nextIdx, err := parseActionChain(runes, actionStart, keys)
		if err != nil {
			return err
		}
		// nextIdx is either n, or points at a comma separating next pair (consume it), or at end
		bind := BindParsed{Keys: keys, Actions: actions, Raw: string(runes[startPair:nextIdx])}
		// Reconstruct raw actions string for convenience
		o.Binds = append(o.Binds, bind)
		i = nextIdx
		if i < n {
			if runes[i] == ',' {
				i++
				if i >= n {
					return fmt.Errorf("key name required")
				}
				continue
			}
			// If parse stopped at something else, advance
			// Should not happen
			continue
		}
	}
	return nil
}

// parseActionChain parses actions from runes[start:], returns actions and index of comma ending pair or n
func parseActionChain(runes []rune, start int, keys []string) ([]ActionParsed, int, error) {
	var actions []ActionParsed
	i := start
	n := len(runes)
	for i <= n {
		if i >= n {
			break
		}
		// Read action name: letters, digits, '-', '/', '+'
		// Handle empty action (e.g., ctrl-a: , trailing +)
		nameStart := i
		for i < n {
			c := runes[i]
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '/' {
				i++
				continue
			}
			break
		}
		name := string(runes[nameStart:i])
		// Special toggle+down / toggle+up
		if name == "toggle" && i+1 < n && runes[i] == '+' {
			// lookahead for down/up as next token followed by '+', ',', '(' or end
			j := i + 1
			k := j
			for k < n && runes[k] >= 'a' && runes[k] <= 'z' {
				k++
			}
			word := string(runes[j:k])
			if word == "down" || word == "up" {
				// treat as single action, if not followed by argument parens
				name = "toggle+" + word
				i = k
				// no argument
				actions = append(actions, ActionParsed{Name: name})
				// after this, expect + or , or end
				if i >= n {
					break
				}
				if runes[i] == '+' {
					i++
					if i >= n {
						return nil, 0, fmt.Errorf("unknown action: %s", "")
					}
					continue
				}
				if runes[i] == ',' {
					break
				}
				// Otherwise will be handled as unknown below?
				continue
			}
		}
		if name == "" {
			// Could be action starting with '+'? e.g., ctrl-a:+accept : first char '+' is chain separator leading to action
			if i < n && runes[i] == '+' {
				// This happens when chain started with '+' (e.g., ":+up") or "++"
				// If we are at start and name empty due '+', consume it and continue to next action
				// But if previous action ended and we consumed '+', we wouldn't be here.
				// Treat a leading '+' as separator: consume and continue if there is a following action name char
				// However "up++down" should error on empty action between ++. That case is handled when after consuming a valid action we see ++.
				// Distinguish: if actions is empty and this is first, allow.
				if len(actions) == 0 {
					i++
					continue
				}
				return nil, 0, fmt.Errorf("unknown action: %s", "")
			}
			return nil, 0, fmt.Errorf("unknown action: %s", string(runes[nameStart:]))
		}
		// Check for argument
		if i < n {
			c := runes[i]
			if c == '(' || c == '[' || c == '{' || c == '<' || c == '~' || c == '!' || c == '@' || c == '#' || c == '$' || c == '%' || c == '^' || c == '&' || c == '*' || c == ';' || c == '/' || c == '|' {
				// argument with paired delimiters. / and | etc are same-char delimiters, ( [ { < are paired closing.
				open := c
				closeCh := open
				paired := true
				switch open {
				case '(':
					closeCh = ')'
				case '[':
					closeCh = ']'
				case '{':
					closeCh = '}'
				case '<':
					closeCh = '>'
				default:
					paired = false
					closeCh = open
				}
				depth := 0
				j := i
				found := -1
				for j < n {
					if paired {
						if runes[j] == open {
							depth++
						} else if runes[j] == closeCh {
							depth--
							if depth == 0 {
								found = j
								break
							}
						}
					} else {
						if j > i && runes[j] == closeCh {
							found = j
							break
						}
					}
					j++
				}
				if found == -1 {
					// No closing: treat rest as argument? Original may parse to end.
					arg := string(runes[i+1:])
					// validation for arg actions
					if err := checkActionArgPresence(name, arg, keys); err != nil {
						return nil, 0, err
					}
					actions = append(actions, ActionParsed{Name: name, Arg: arg, HasArg: true, ArgStyle: byte(open)})
					i = n
					break
				}
				arg := string(runes[i+1 : found])
				if err := checkActionArgPresence(name, arg, keys); err != nil {
					return nil, 0, err
				}
				// For no-arg actions, presence of (arg) makes the whole token unknown
				if noArgActions[name] {
					return nil, 0, fmt.Errorf("unknown action: %s", name+"("+arg+")")
				}
				if !argActions[name] && name != "put" && name != "change-multi" {
					// Unknown action name
					return nil, 0, fmt.Errorf("unknown action: %s", name)
				}
				actions = append(actions, ActionParsed{Name: name, Arg: arg, HasArg: true, ArgStyle: byte(open)})
				i = found + 1
				// after arg, expect + , or end
				if i >= n {
					break
				}
				if runes[i] == '+' {
					i++
					if i >= n {
						return nil, 0, fmt.Errorf("unknown action: %s", "")
					}
					// check for empty next action (++)
					if runes[i] == '+' {
						return nil, 0, fmt.Errorf("unknown action: %s", "")
					}
					continue
				}
				if runes[i] == ',' {
					break
				}
				// If next is something else, treat as start of? Continue loop; will likely error
				continue
			} else if c == ':' {
				// colon argument: consumes rest of whole bind string
				arg := string(runes[i+1:])
				if err := checkActionArgPresence(name, arg, keys); err != nil {
					return nil, 0, err
				}
				if noArgActions[name] {
					return nil, 0, fmt.Errorf("unknown action: %s", name)
				}
				if !argActions[name] && name != "put" && name != "change-multi" {
					return nil, 0, fmt.Errorf("unknown action: %s", name)
				}
				actions = append(actions, ActionParsed{Name: name, Arg: arg, HasArg: true, ArgStyle: ':'})
				i = n
				break
			} else if c == '+' {
				// end of this action, next action follows
				// validate this action (no arg)
				if err := checkBareAction(name, keys); err != nil {
					return nil, 0, err
				}
				actions = append(actions, ActionParsed{Name: name})
				i++ // consume '+'
				if i >= n {
					return nil, 0, fmt.Errorf("unknown action: %s", "")
				}
				if runes[i] == '+' {
					return nil, 0, fmt.Errorf("unknown action: %s", "")
				}
				continue
			} else if c == ',' {
				if err := checkBareAction(name, keys); err != nil {
					return nil, 0, err
				}
				actions = append(actions, ActionParsed{Name: name})
				break
			} else {
				// Unexpected char after name: treat overall as unknown action including up to next +/,?
				// e.g., abort(x) handled above; other like "up;" ?
				return nil, 0, fmt.Errorf("unknown action: %s", name)
			}
		} else {
			// end of string
			if err := checkBareAction(name, keys); err != nil {
				return nil, 0, err
			}
			actions = append(actions, ActionParsed{Name: name})
			break
		}
	}
	return actions, i, nil
}

func checkBareAction(name string, keys []string) error {
	if name == "put" {
		// need a printable single key among keys
		for _, k := range keys {
			if isPrintableSingleKey(k) {
				return nil
			}
		}
		return fmt.Errorf("unable to put non-printable character")
	}
	if noArgActions[name] {
		return nil
	}
	if name == "change-multi" {
		return nil
	}
	// argActions without arg are unknown
	// also unknown names
	return fmt.Errorf("unknown action: %s", name)
}

func checkActionArgPresence(name, arg string, keys []string) error {
	if noArgActions[name] {
		// Caller handles unknown; but for colon style, no-arg with colon arg is also unknown; we signal there.
		return nil
	}
	if argActions[name] || name == "put" || name == "change-multi" {
		return validateActionWithArg(name, arg, keys)
	}
	return fmt.Errorf("unknown action: %s", name)
}

var _ = utf8.RuneCountInString
EOF
"}

