package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// parsePreviewWindow parses a preview-window value and returns opts
func parsePreviewWindow(v string) (PreviewWindowOpts, error) {
	var opts PreviewWindowOpts
	opts.Position = "right"
	if strings.TrimSpace(v) == "" {
		// empty: default-ish no change; caller may treat as valid
		fifty := 50.0
		opts.SizePercent = &fifty
		opts.SizeSet = true
		return opts, nil
	}
	// split by commas outside parentheses
	tokens := splitPreviewTokens(v)
	// initialize with defaults for fields not set? Validation only needs position/size parsing
	var havePos bool
	for _, token := range tokens {
		if token == "" {
			continue
		}
		if strings.HasPrefix(token, "<") {
			// alternative layout
			// must be <NUMBER[%](alt)>
			// Find closing ')'
			openParen := strings.Index(token, "(")
			if openParen < 0 || !strings.HasSuffix(token, ")") {
				return opts, fmt.Errorf("invalid preview window option: %s", token)
			}
			threshold := token[1:openParen]
			// threshold is size: int or int%
			if threshold == "" {
				return opts, fmt.Errorf("invalid preview window option: %s", token)
			}
			// validate threshold as size (int or percent int)
			if err := validatePreviewSizeToken(threshold, token); err != nil {
				// For <x etc, original reports token, not threshold
				if strings.Contains(err.Error(), "window size too large") {
					return opts, err
				}
				return opts, fmt.Errorf("invalid preview window option: %s", token)
			}
			alt := token[openParen+1 : len(token)-1]
			if _, err := parsePreviewWindow(alt); err != nil {
				return opts, err
			}
			continue
		}
		if strings.HasPrefix(token, "+") {
			if err := validateScrollToken(token); err != nil {
				return opts, fmt.Errorf("invalid preview window option: %s", token)
			}
			opts.Scroll = token
			continue
		}
		if strings.HasPrefix(token, "~") {
			if err := validateHeaderToken(token); err != nil {
				return opts, fmt.Errorf("invalid preview window option: %s", token)
			}
			// parse number
			n, _ := strconv.Atoi(token[1:])
			opts.HeaderLines = n
			continue
		}
		// colon segments
		segs := strings.Split(token, ":")
		for _, seg := range segs {
			if seg == "" {
				return opts, fmt.Errorf("invalid preview window option: %s", seg)
			}
			switch seg {
			case "up", "down", "left", "right":
				opts.Position = seg
				havePos = true
				_ = havePos
				continue
			case "wrap":
				opts.Wrap = true; continue
			case "nowrap":
				opts.Wrap = false; continue
			case "cycle":
				opts.Cycle = true; continue
			case "nocycle":
				opts.Cycle = false; continue
			case "follow":
				opts.Follow = true; continue
			case "nofollow":
				opts.Follow = false; continue
			case "info":
				opts.Info = true; continue
			case "noinfo":
				opts.Info = false; continue
			case "hidden":
				opts.Hidden = true; continue
			case "nohidden":
				opts.Hidden = false; continue
			case "default":
				continue
			case "border":
				opts.Border = "rounded"; opts.BorderSet = true; continue
			case "noborder":
				opts.Border = "none"; opts.BorderSet = true; continue
			}
			if strings.HasPrefix(seg, "border-") {
				style := seg[len("border-"):]
				if err := validateBorder(style); err != nil {
					return opts, fmt.Errorf("invalid preview window option: %s", seg)
				}
				opts.Border = style; opts.BorderSet = true
				continue
			}
			if validateBorder(seg) == nil {
				// border style alone
				opts.Border = seg; opts.BorderSet = true
				continue
			}
			if strings.HasPrefix(seg, "+") {
				if err := validateScrollToken(seg); err != nil {
					return opts, fmt.Errorf("invalid preview window option: %s", seg)
				}
				opts.Scroll = seg; continue
			}
			if strings.HasPrefix(seg, "~") {
				if err := validateHeaderToken(seg); err != nil {
					return opts, fmt.Errorf("invalid preview window option: %s", seg)
				}
				n, _ := strconv.Atoi(seg[1:]); opts.HeaderLines = n; continue
			}
			// size token
			if err := applyPreviewSize(&opts, seg); err != nil {
				return opts, err
			}
		}
	}
	return opts, nil
}

func validatePreviewSizeToken(seg, whole string) error {
	if strings.HasSuffix(seg, "%") {
		num := seg[:len(seg)-1]
		if _, err := strconv.Atoi(num); err != nil {
			return fmt.Errorf("invalid preview window option: %s", whole)
		}
		v, _ := strconv.Atoi(num)
		if v > 99 {
			return fmt.Errorf("window size too large (max: 99%%)")
		}
		return nil
	}
	if _, err := strconv.Atoi(seg); err != nil {
		return fmt.Errorf("invalid preview window option: %s", whole)
	}
	return nil
}

func applyPreviewSize(opts *PreviewWindowOpts, seg string) error {
	if strings.HasSuffix(seg, "%") {
		num := seg[:len(seg)-1]
		v, err := strconv.Atoi(num)
		if err != nil {
			return fmt.Errorf("invalid preview window option: %s", seg)
		}
		if v > 99 {
			return fmt.Errorf("window size too large (max: 99%%)")
		}
		f := float64(v)
		opts.SizePercent = &f
		opts.SizeSet = true
		opts.Size = 0
		return nil
	}
	v, err := strconv.Atoi(seg)
	if err != nil {
		return fmt.Errorf("invalid preview window option: %s", seg)
	}
	opts.Size = v
	opts.SizePercent = nil
	opts.SizeSet = true
	return nil
}

func validateScrollToken(tok string) error {
	// +SCROLL..., examples: +10, +{2}, +3, +10-3, +1+2, +10/2 , +{2}+3/2
	rest := tok[1:]
	if rest == "" {
		return fmt.Errorf("invalid")
	}
	// Denominator check: if contains '/', denom must be non-zero integer or placeholder?
	// Simplify: allowed characters are digits, +, -, /, {, }, and inside braces digits
	// Reject "++" at start and empty denom / zero denom
	if strings.HasPrefix(rest, "+") {
		return fmt.Errorf("invalid")
	}
	for _, c := range rest {
		if (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '/' || c == '{' || c == '}' || c == '_' {
			continue
		}
		return fmt.Errorf("invalid")
	}
	if idx := strings.Index(rest, "/"); idx >= 0 {
		denom := rest[idx+1:]
		// denom may be like "2" or could contain +/- later? Take up to +/-
		// If denom is "0" or empty -> invalid
		d := denom
		// extract leading digits
		i := 0
		for i < len(d) && d[i] >= '0' && d[i] <= '9' { i++ }
		if i == 0 {
			// could be placeholder {..}
			if !strings.HasPrefix(d, "{") {
				return fmt.Errorf("invalid")
			}
		} else {
			v, _ := strconv.Atoi(d[:i])
			if v == 0 {
				return fmt.Errorf("invalid")
			}
		}
	}
	return nil
}

func validateHeaderToken(tok string) error {
	rest := tok[1:]
	if rest == "" {
		return fmt.Errorf("invalid")
	}
	if _, err := strconv.Atoi(rest); err != nil {
		return fmt.Errorf("invalid")
	}
	v, _ := strconv.Atoi(rest)
	if v < 0 {
		return fmt.Errorf("invalid")
	}
	return nil
}

func splitPreviewTokens(v string) []string {
	var tokens []string
	depth := 0
	start := 0
	for i, c := range v {
		if c == '(' { depth++ }
		if c == ')' && depth > 0 { depth-- }
		if c == ',' && depth == 0 {
			tokens = append(tokens, v[start:i])
			start = i+1
		}
	}
	tokens = append(tokens, v[start:])
	return tokens
}

// validate and parse height
func parseHeight(v string) (HeightSpec, error) {
	var hs HeightSpec
	hs.Raw = v
	orig := v
	if strings.HasPrefix(v, "~") {
		hs.Adaptive = true
		v = v[1:]
		if strings.HasPrefix(v, "-") {
			// check if numeric after '-' : -5 etc => special error if adaptive and value negative
			// We'll handle after parsing value
		}
	}
	if v == "" {
		return hs, fmt.Errorf("not a valid integer: %s", v)
	}
	if strings.HasSuffix(v, "%") {
		hs.Percent = true
		numStr := v[:len(v)-1]
		f, err := strconv.ParseFloat(numStr, 64)
		if err != nil {
			return hs, fmt.Errorf("not a valid number: %s", numStr)
		}
		if hs.Adaptive && f < 0 {
			return hs, fmt.Errorf("negative(-) height is not compatible with adaptive(~) height")
		}
		if f > 100 {
			return hs, fmt.Errorf("height too large (max: 100%%)")
		}
		hs.Value = f
		return hs, nil
	}
	// non-percent: must be integer
	if iv, err := strconv.Atoi(v); err == nil {
		if hs.Adaptive && iv < 0 {
			return hs, fmt.Errorf("negative(-) height is not compatible with adaptive(~) height")
		}
		hs.Value = float64(iv)
		return hs, nil
	}
	// if parses as float, special message
	if _, err := strconv.ParseFloat(v, 64); err == nil {
		return hs, fmt.Errorf("height (without %%) must be a non-negative integer")
	}
	_ = orig
	return hs, fmt.Errorf("not a valid integer: %s", v)
}

func parseLabelPosValue(v string, requiredMsg string) (string, error) {
	if v == "" {
		return "", fmt.Errorf("not a valid integer: %s", v)
	}
	// If value is exactly center/top/bottom, ok
	// Implement reverse-scan logic described
	parts := strings.Split(v, ":")
	// scan from right
	for idx := len(parts) - 1; idx >= 0; idx-- {
		p := parts[idx]
		if p == "center" || p == "top" || p == "bottom" {
			continue
		}
		if _, err := strconv.Atoi(p); err != nil {
			return "", fmt.Errorf("not a valid integer: %s", p)
		}
		// found position integer, stop
		return v, nil
	}
	return v, nil
	_ = requiredMsg
}

func displayWidth(s string) int {
	// approximation of rune display width (east asian wide =2)
	w := 0
	for _, r := range s {
		w += runeDisplayWidth(r)
	}
	return w
}

func runeDisplayWidth(r rune) int {
	if r == 0 {
		return 0
	}
	if r < 0x20 || (r >= 0x7f && r < 0xa0) {
		return 0
	}
	// Wide ranges (rough)
	if (r >= 0x1100 && r <= 0x115F) || r == 0x2329 || r == 0x232A ||
		(r >= 0x2E80 && r <= 0x4E00) || (r >= 0x4E00 && r <= 0xA4C6) ||
		(r >= 0xA960 && r <= 0xA97C) || (r >= 0xAC00 && r <= 0xD7A3) ||
		(r >= 0xF900 && r <= 0xFAFF) || (r >= 0xFE10 && r <= 0xFE19) ||
		(r >= 0xFE30 && r <= 0xFE52) || (r >= 0xFE54 && r <= 0xFE66) ||
		(r >= 0xFE68 && r <= 0xFE6B) || (r >= 0xFF00 && r <= 0xFF60) ||
		(r >= 0xFFE0 && r <= 0xFFE6) || (r >= 0x1F300 && r <= 0x1F64F) ||
		(r >= 0x1F900 && r <= 0x1F9FF) || (r >= 0x20000 && r <= 0x3FFFD) {
		return 2
	}
	return 1
}

// Color validation
var colorNames = map[string]bool{
	"fg": true, "bg": true, "hl": true,
	"list-fg": true, "selected-fg": true, "preview-fg": true, "list-bg": true, "selected-bg": true, "preview-bg": true, "input-bg": true, "header-bg": true, "footer-bg": true,
	"selected-hl": true, "current-fg": true, "fg+": true, "current-bg": true, "bg+": true, "gutter": true, "current-hl": true, "hl+": true,
	"alt-bg": true, "alt-gutter": true, "query": true, "input-fg": true, "ghost": true, "disabled": true, "info": true,
	"border": true, "list-border": true, "scrollbar": true, "separator": true, "gap-line": true, "preview-border": true, "preview-scrollbar": true, "input-border": true, "header-border": true, "footer-border": true,
	"label": true, "list-label": true, "preview-label": true, "input-label": true, "header-label": true, "footer-label": true,
	"prompt": true, "pointer": true, "marker": true, "spinner": true, "header": true, "header-fg": true, "footer": true, "footer-fg": true, "nth": true, "nomatch": true,
	"current": false, // marker invalid
}

var ansiColorNames = map[string]bool{
	"black": true, "red": true, "green": true, "yellow": true, "blue": true, "magenta": true, "cyan": true, "white": true,
	"bright-black": true, "gray": true, "grey": true, "bright-red": true, "bright-green": true, "bright-yellow": true, "bright-blue": true, "bright-magenta": true, "bright-cyan": true, "bright-white": true,
}

var ansiAttrs = map[string]bool{
	"regular": true, "strip": true, "bold": true, "underline": true, "underline-double": true, "underline-curly": true, "underline-dotted": true, "underline-dashed": true,
	"reverse": true, "dim": true, "italic": true, "strikethrough": true,
}

func validateColorSpec(v string) error {
	if v == "" {
		return nil
	}
	// split by comma and/or whitespace
	fields := strings.FieldsFunc(v, func(r rune) bool { return r == ',' || r == ' ' || r == '\t' || r == '\n' || r == '\r' })
	for _, entry := range fields {
		if entry == "" {
			continue
		}
		// base schemes alone
		lowerEntry := strings.ToLower(entry)
		if lowerEntry == "dark" || lowerEntry == "light" || lowerEntry == "base16" || lowerEntry == "16" || lowerEntry == "bw" {
			continue
		}
		parts := strings.Split(entry, ":")
		if len(parts) < 2 {
			return fmt.Errorf("invalid color specification: %s", entry)
		}
		name := parts[0]
		if name == "" {
			return fmt.Errorf("invalid color specification: %s", entry)
		}
		// Names might be like fg+ with space trimmed? Already fields
		// Check color name validity
		if _, ok := colorNames[name]; !ok || name == "current" {
			return fmt.Errorf("invalid color specification: %s", entry)
		}
		// For nth, all following parts must be attributes
		if name == "nth" {
			for _, p := range parts[1:] {
				if p == "" { continue }
				if !ansiAttrs[p] {
					return fmt.Errorf("only ANSI attributes are allowed for 'nth' (regular, bold, underline, reverse, dim, italic, strikethrough)")
				}
			}
			continue
		}
		// parts[1] is color (may be empty), rest attributes
		if len(parts) >= 2 {
			col := parts[1]
			if col != "" {
				if err := validateAnsiColor(col); err != nil {
					return fmt.Errorf("invalid color specification: %s", entry)
				}
			}
			for _, attr := range parts[2:] {
				if attr == "" { continue }
				if !ansiAttrs[attr] {
					return fmt.Errorf("invalid color specification: %s", entry)
				}
			}
		}
	}
	return nil
}

func validateAnsiColor(col string) error {
	if col == "" { return nil }
	// attribute alone as color? e. fg:italic, fg:bold  observed valid. If col is an attribute name, accept as attribute-only
	if ansiAttrs[col] {
		return nil
	}
	if col == "-1" {
		return nil
	}
	if strings.HasPrefix(col, "#") {
		hex := col[1:]
		if len(hex) != 6 {
			return fmt.Errorf("invalid")
		}
		for _, c := range hex {
			if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
				return fmt.Errorf("invalid")
			}
		}
		return nil
	}
	if ansiColorNames[strings.ToLower(col)] {
		// but bright-grey is invalid (in map? we have grey, bright-??)  -- check: gray/grey aliases are only for bright-black, not generic bright-grey
		if col == "bright-grey" || col == "bright-gray" {
			return fmt.Errorf("invalid")
		}
		return nil
	}
	// numeric 0-255
	if v, err := strconv.Atoi(col); err == nil {
		if v >= 0 && v <= 255 {
			return nil
		}
		return fmt.Errorf("invalid")
	}
	return fmt.Errorf("invalid")
}

// parseLong handles --name[=value]
func (o *Options) parseLong(arg string, args []string, idx int) (int, error) {
	// arg starts with --
	rest := arg[2:]
	name := rest
	value := ""
	hasValue := false
	if eq := strings.Index(rest, "="); eq >= 0 {
		name = rest[:eq]
		value = rest[eq+1:]
		hasValue = true
	}
	// helper closures
	nextRequired := func(requiredMsg string) (string, int, error) {
		if hasValue {
			return value, 1, nil
		}
		if idx+1 >= len(args) {
			return "", 1, fmt.Errorf("%s", requiredMsg)
		}
		return args[idx+1], 2, nil
	}
	nextOptional := func() (string, bool, int) {
		// returns value, present, consumed
		if hasValue {
			return value, true, 1
		}
		if idx+1 < len(args) {
			nxt := args[idx+1]
			if nxt == "" {
				return nxt, true, 2
			}
			r, _ := utf8.DecodeRuneInString(nxt)
			if r != '-' && r != '+' {
				return nxt, true, 2
			}
		}
		return "", false, 1
	}
	unexpected := func() error {
		if hasValue {
			return fmt.Errorf("unexpected value for --%s: %s", name, value)
		}
		return nil
	}

	// Bool options table
	if action, ok := boolOptions[name]; ok {
		if err := unexpected(); err != nil { return 1, err }
		action(o)
		return 1, nil
	}
	// Mode options (version/help/man/shell)
	switch name {
	case "version", "help", "man", "bash", "zsh", "fish":
		if err := unexpected(); err != nil { return 1, err }
		o.Mode = name
		return 1, nil
	}
	// Special optional int options
	switch name {
	case "sort":
		if hasValue {
			n, err := strconv.Atoi(value)
			if err != nil { return 1, fmt.Errorf("not a valid integer: %s", value) }
			o.Sort = n != 0
		} else {
			o.Sort = true
		}
		return 1, nil
	case "multi":
		if hasValue {
			n, err := strconv.Atoi(value)
			if err != nil { return 1, fmt.Errorf("not a valid integer: %s", value) }
			o.MultiSet = true
			o.Multi = n
		} else {
			o.MultiSet = true
			o.Multi = -1
		}
		return 1, nil
	case "gap":
		if hasValue {
			n, err := strconv.Atoi(value)
			if err != nil { return 1, fmt.Errorf("not a valid integer: %s", value) }
			o.Gap = n
		} else {
			o.Gap = 1
		}
		return 1, nil
	case "gap-line":
		if v, present, consumed := nextOptional(); present {
			o.GapLine = v; o.GapLineSet = true; return consumed, nil
		}
		// default
		if o.Unicode { o.GapLine = "┈" } else { o.GapLine = "-" }
		o.GapLineSet = true
		return 1, nil
	case "scrollbar":
		if v, present, consumed := nextOptional(); present {
			if err := validateScrollbar(v); err != nil { return 1, err }
			o.Scrollbar = v; o.ScrollbarSet = true; return consumed, nil
		}
		o.Scrollbar = "│"; o.ScrollbarSet = true // default approximation
		return 1, nil
	case "color":
		if v, present, consumed := nextOptional(); present {
			if err := validateColorSpec(v); err != nil { return 1, err }
			o.ColorSpec = v; return consumed, nil
		}
		// bare color: no spec
		return 1, nil
	case "tmux":
		if v, present, consumed := nextOptional(); present {
			if err := validateTmux(v); err != nil { return 1, err }
			o.Tmux = true; o.TmuxOpts = v; return consumed, nil
		}
		o.Tmux = true; o.TmuxOpts = "center,50%"
		return 1, nil
	case "listen", "listen-unsafe":
		unsafe := name == "listen-unsafe"
		if v, present, consumed := nextOptional(); present {
			if err := validateListen(v); err != nil { return 1, err }
			o.Listen = v; o.ListenSet = true; o.ListenUnsafe = unsafe; return consumed, nil
		}
		o.Listen = ""; o.ListenSet = true; o.ListenUnsafe = unsafe
		return 1, nil
	}
	// Border optional options
	borderOptions := map[string]*string{
		"border": &o.Border, "list-border": &o.ListBorder, "input-border": &o.InputBorder,
		"header-border": &o.HeaderBorder, "footer-border": &o.FooterBorder, "preview-border": nil, // special
	}
	if ptr, ok := borderOptions[name]; ok {
		if v, present, consumed := nextOptional(); present {
			if err := validateBorder(v); err != nil { return 1, err }
			if name == "preview-border" {
				// short for preview-window border
				o.PreviewOpts.Border = v; o.PreviewOpts.BorderSet = true
			} else {
				*ptr = v
				if name == "border" { o.BorderSet = true }
			}
			return consumed, nil
		}
		// bare defaults rounded
		if name == "preview-border" {
			o.PreviewOpts.Border = "rounded"; o.PreviewOpts.BorderSet = true
		} else {
			*ptr = "rounded"
			if name == "border" { o.BorderSet = true }
		}
		return 1, nil
	}
	if name == "header-lines-border" {
		if v, present, consumed := nextOptional(); present {
			if err := validateBorder(v); err != nil { return 1, err }
			o.HeaderLinesBorder = v; o.HeaderLinesBorderSet = true; return consumed, nil
		}
		o.HeaderLinesBorder = "rounded"; o.HeaderLinesBorderSet = true
		return 1, nil
	}

	// Required value options
	type reqHandler struct {
		required string
		fn func(string) error
	}
	req := map[string]reqHandler{}
	// Populate using closures
	req["scheme"] = reqHandler{"scoring scheme required (default|path|history)", func(v string) error { return o.setScheme(v) }}
	req["nth"] = reqHandler{"nth expression required", func(v string) error { return o.setNth(v) }}
	req["with-nth"] = reqHandler{"nth expression required", func(v string) error { return o.setWithNth(v) }}
	req["accept-nth"] = reqHandler{"nth expression required", func(v string) error { return o.setAcceptNth(v) }}
	req["delimiter"] = reqHandler{"delimiter required", func(v string) error { return o.setDelimiter(v) }}
	req["tail"] = reqHandler{"number of items to keep required", func(v string) error {
		n, err := strconv.Atoi(v)
		if err != nil { return fmt.Errorf("number of items to keep required") }
		if n <= 0 { return fmt.Errorf("number of items to keep must be a positive integer") }
		o.Tail = n; return nil
	}}
	req["tiebreak"] = reqHandler{"sort criterion required", func(v string) error { return o.setTiebreak(v) }}
	req["algo"] = reqHandler{"algorithm required (v1|v2)", func(v string) error {
		if v == "v1" || v == "v2" { o.Algo = v; return nil }
		return fmt.Errorf("invalid algorithm (expected: v1 or v2)")
	}}
	req["style"] = reqHandler{"preset name required: [default|minimal|full[:BORDER_STYLE]]", func(v string) error { return o.applyStyle(v) }}
	req["height"] = reqHandler{"height required: [~]HEIGHT[%]", func(v string) error {
		hs, err := parseHeight(v); if err != nil { return err }; o.Height = hs; o.HeightSet = true; o.HeightVal = v; return nil
	}}
	req["min-height"] = reqHandler{"minimum height required: HEIGHT[+]", func(v string) error {
		orig := v
		plus := false
		if strings.HasSuffix(v, "+") { plus = true; v = v[:len(v)-1] }
		n, err := strconv.Atoi(v)
		if err != nil || n < 0 { return fmt.Errorf("minimum height must be a non-negative integer") }
		_ = orig; o.MinHeight = n; o.MinHeightPlus = plus; return nil
	}}
	req["layout"] = reqHandler{"layout required (default / reverse / reverse-list)", func(v string) error {
		switch v {
		case "default", "reverse", "reverse-list": o.Layout = v; return nil
		default: return fmt.Errorf("invalid layout (expected: default / reverse / reverse-list)")
		}
	}}
	req["margin"] = reqHandler{"margin required (TRBL / TB,RL / T,RL,B / T,R,B,L)", func(v string) error {
		if err := validateMarginPadding(v, "margin"); err != nil { return err }; o.Margin = v; return nil
	}}
	req["padding"] = reqHandler{"padding required (TRBL / TB,RL / T,RL,B / T,R,B,L)", func(v string) error {
		if err := validateMarginPadding(v, "padding"); err != nil { return err }; o.Padding = v; return nil
	}}
	req["border-label"] = reqHandler{"label required", func(v string) error { o.BorderLabel = v; return nil }}
	req["list-label"] = reqHandler{"label required", func(v string) error { o.ListLabel = v; return nil }}
	req["input-label"] = reqHandler{"input label required", func(v string) error { o.InputLabel = v; return nil }}
	req["header-label"] = reqHandler{"header label required", func(v string) error { o.HeaderLabel = v; return nil }}
	req["footer-label"] = reqHandler{"footer label required", func(v string) error { o.FooterLabel = v; return nil }}
	req["preview-label"] = reqHandler{"preview label required", func(v string) error { o.PreviewLabel = v; return nil }}
	// label positions
	makeLabelPos := func(required string, dst *string) reqHandler {
		return reqHandler{required, func(v string) error {
			if _, err := parseLabelPosValue(v, required); err != nil { return err }; *dst = v; return nil
		}}
	}
	req["border-label-pos"] = makeLabelPos("label position required (positive or negative integer or 'center')", &o.BorderLabelPos)
	req["list-label-pos"] = makeLabelPos("label position required (positive or negative integer or 'center')", &o.ListLabelPos)
	req["input-label-pos"] = makeLabelPos("input label position required (positive or negative integer or 'center')", &o.InputLabelPos)
	req["header-label-pos"] = makeLabelPos("header label position required (positive or negative integer or 'center')", &o.HeaderLabelPos)
	req["footer-label-pos"] = makeLabelPos("footer label position required (positive or negative integer or 'center')", &o.FooterLabelPos)
	req["preview-label-pos"] = makeLabelPos("preview label position required (positive or negative integer or 'center')", &o.PreviewLabelPos)
	req["freeze-left"] = reqHandler{"number of fields required", func(v string) error {
		n, err := strconv.Atoi(v); if err != nil { return fmt.Errorf("number of fields required") }; if n < 0 { return fmt.Errorf("number of fields to freeze must be a non-negative integer") }; o.FreezeLeft = n; return nil
	}}
	req["freeze-right"] = reqHandler{"number of fields required", func(v string) error {
		n, err := strconv.Atoi(v); if err != nil { return fmt.Errorf("number of fields required") }; if n < 0 { return fmt.Errorf("number of fields to freeze must be a non-negative integer") }; o.FreezeRight = n; return nil
	}}
	req["scroll-off"] = reqHandler{"scroll offset required", func(v string) error {
		n, err := strconv.Atoi(v); if err != nil { return fmt.Errorf("scroll offset required") }; if n < 0 { return fmt.Errorf("scroll offset must be a non-negative integer") }; o.ScrollOff = n; return nil
	}}
	req["hscroll-off"] = reqHandler{"hscroll offset required", func(v string) error {
		n, err := strconv.Atoi(v); if err != nil { return fmt.Errorf("hscroll offset required") }; if n < 0 { return fmt.Errorf("hscroll offset must be a non-negative integer") }; o.HscrollOff = n; return nil
	}}
	req["jump-labels"] = reqHandler{"label characters required", func(v string) error {
		if v == "" { return fmt.Errorf("empty jump labels") }; o.JumpLabels = v; return nil
	}}
	req["gutter"] = reqHandler{"gutter character required", func(v string) error {
		if displayWidth(v) != 1 { return fmt.Errorf("gutter display width should be 1") }; o.Gutter = v; return nil
	}}
	req["gutter-raw"] = reqHandler{"gutter character for raw mode required", func(v string) error {
		if displayWidth(v) != 1 { return fmt.Errorf("gutter display width should be 1") }; o.GutterRaw = v; return nil
	}}
	req["pointer"] = reqHandler{"pointer sign required", func(v string) error {
		if displayWidth(v) > 2 { return fmt.Errorf("pointer display width should be up to 2") }; o.Pointer = v; return nil
	}}
	req["marker"] = reqHandler{"marker sign required", func(v string) error {
		if displayWidth(v) > 2 { return fmt.Errorf("marker display width should be up to 2") }; o.Marker = v; return nil
	}}
	req["marker-multi-line"] = reqHandler{"marker sign for multi-line entries required", func(v string) error {
		w := displayWidth(v); if w != 0 && w != 3 && w != 6 { return fmt.Errorf("invalid total marker width: %d (expected: 0, 3 or 6)", w) }; o.MarkerMultiLine = v; return nil
	}}
	req["ellipsis"] = reqHandler{"ellipsis string required", func(v string) error { o.Ellipsis = v; return nil }}
	req["tabstop"] = reqHandler{"tab stop required", func(v string) error {
		n, err := strconv.Atoi(v); if err != nil { return fmt.Errorf("tab stop required") }; if n <= 0 { return fmt.Errorf("tab stop must be a positive integer") }; o.Tabstop = n; return nil
	}}
	req["prompt"] = reqHandler{"prompt string required", func(v string) error { o.Prompt = v; return nil }}
	req["info"] = reqHandler{"info style required", func(v string) error {
		if err := validateInfo(v); err != nil { return err }; o.InfoStyle = v; return nil
	}}
	req["info-command"] = reqHandler{"info command required", func(v string) error { o.InfoCommand = v; return nil }}
	req["separator"] = reqHandler{"separator character required", func(v string) error { o.Separator = v; o.SeparatorSet = true; return nil }}
	req["ghost"] = reqHandler{"ghost text required", func(v string) error { o.Ghost = v; return nil }}
	req["preview"] = reqHandler{"preview command required", func(v string) error { o.PreviewCmd = v; o.PreviewSet = true; return nil }}
	req["preview-window"] = reqHandler{"preview window layout required: [up|down|left|right][,SIZE[%]][,border-STYLE][,wrap][,cycle][,hidden][,+SCROLL[OFFSETS][/DENOM]][,~HEADER_LINES][,default]", func(v string) error {
		pw, err := parsePreviewWindow(v); if err != nil { return err }; o.PreviewOpts = pw; o.PreviewWindow = v; return nil
	}}
	req["header"] = reqHandler{"header string required", func(v string) error { o.Header = v; return nil }}
	req["header-lines"] = reqHandler{"number of header lines required", func(v string) error {
		// special: bare --no-header-lines is bool op; but this handler for value forms
		n, err := strconv.Atoi(v); if err != nil { return fmt.Errorf("number of header lines required") }; if n < 0 { return fmt.Errorf("header lines must be a non-negative integer") }; o.HeaderLines = n; return nil
	}}
	req["footer"] = reqHandler{"footer string required", func(v string) error { o.Footer = v; return nil }}
	req["query"] = reqHandler{"query string required", func(v string) error { o.Query = v; return nil }}
	req["filter"] = reqHandler{"query string required", func(v string) error { f:=v; o.Filter=&f; return nil }}
	req["expect"] = reqHandler{"key names required", func(v string) error {
		if v == "" { return fmt.Errorf("key names required") }
		parts := strings.Split(v, ",")
		for _, p := range parts {
			if p == "" { continue }
			if err := validateKeyName(p); err != nil { return err }
			o.Expect = append(o.Expect, p)
		}
		return nil
	}}
	req["bind"] = reqHandler{"bind expression required", func(v string) error { return o.addBind(v) }}
	req["with-shell"] = reqHandler{"shell command and flags required", func(v string) error { o.WithShell = v; return nil }}
	req["walker"] = reqHandler{"walker options required [file][,dir][,follow][,hidden]", func(v string) error { return o.setWalker(v) }}
	req["walker-root"] = reqHandler{"no directory specified", func(v string) error {
		// walker-root can consume multiple following args in CLI? It's declared as DIR [...] (multiple)
		// In this handler, single value; caller will handle extra consumption in parse loop? Keep single.
		if v == "" {
			// empty value is accepted as a root? Observed --walker-root= accepted
			o.WalkerRoots = append(o.WalkerRoots, v); return nil
		}
		o.WalkerRoots = append(o.WalkerRoots, v); return nil
	}}
	req["walker-skip"] = reqHandler{"directory names to ignore required", func(v string) error { o.WalkerSkip = v; return nil }}
	req["history"] = reqHandler{"history file path required", func(v string) error {
		// validate file can be opened/read (as fzf does at option parse time)
		if err := validateHistoryFile(v); err != nil { return err }
		o.HistoryFile = v; return nil
	}}
	req["history-size"] = reqHandler{"history max size required", func(v string) error {
		n, err := strconv.Atoi(v); if err != nil { return fmt.Errorf("history max size required") }; if n <= 0 { return fmt.Errorf("history max must be a positive integer") }; o.HistorySize = n; return nil
	}}
	req["tty-default"] = reqHandler{"tty device name required", func(v string) error { o.TtyDefault = v; o.NoTtyDefault = false; return nil }}
	req["wrap-sign"] = reqHandler{"wrap sign required", func(v string) error { o.WrapSign = v; return nil }}

	if h, ok := req[name]; ok {
		v, consumed, err := nextRequired(h.required)
		if err != nil { return consumed, err }
		if err := h.fn(v); err != nil { return consumed, err }
		// Special walker-root: it consumes following arguments that are directories (don't look like options) ?
		if name == "walker-root" {
			// Consume additional args while next doesn't start with '-' or '+'? In fzf, --walker-root=DIR [...]  maybe only when separate arg form and subsequent args up to next option
			// Observed test: --walker-root without = gave "no directory specified" when next was -f (so it uses nextRequired)
			// With value via next token, further tokens that are not option-like are also roots.
			extra := 0
			for idx+consumed+extra < len(args) {
				nxt := args[idx+consumed+extra]
				if nxt == "" || nxt[0] == '-' || nxt[0] == '+' {
					break
				}
				o.WalkerRoots = append(o.WalkerRoots, nxt)
				extra++
			}
			return consumed + extra, nil
		}
		return consumed, nil
	}
	// unknown
	if strings.Contains(arg, "=") {
		return 1, fmt.Errorf("unknown option: --%s", name)
	}
	return 1, fmt.Errorf("unknown option: --%s", name)
}

func validateScrollbar(v string) error {
	// count runes
	if utf8.RuneCountInString(v) > 2 {
		return fmt.Errorf("--scrollbar should be given one or two characters")
	}
	return nil
}

func validateTmux(v string) error {
	if v == "" {
		return fmt.Errorf("invalid tmux option: %s (expected: [center|top|bottom|left|right][,SIZE[%%]][,SIZE[%%][,border-native]])", v)
	}
	parts := strings.Split(v, ",")
	for _, p := range parts {
		if p == "" { return fmt.Errorf("invalid tmux option: %s (expected: [center|top|bottom|left|right][,SIZE[%%]][,SIZE[%%][,border-native]])", v) }
		switch p {
		case "center","top","bottom","left","right","border-native":
			continue
		}
		// size: int or int%
		if strings.HasSuffix(p, "%") {
			num := p[:len(p)-1]
			f, err := strconv.ParseFloat(num, 64)
			if err != nil || f < 0 || f > 100 { // 200% earlier failed, what about >100 absolute? Size percent max 100?
				return fmt.Errorf("invalid tmux option: %s (expected: [center|top|bottom|left|right][,SIZE[%%]][,SIZE[%%][,border-native]])", v)
			}
			continue
		}
		if _, err := strconv.Atoi(p); err != nil {
			return fmt.Errorf("invalid tmux option: %s (expected: [center|top|bottom|left|right][,SIZE[%%]][,SIZE[%%][,border-native]])", v)
		}
	}
	return nil
}

func validateListen(v string) error {
	if strings.HasSuffix(v, ".sock") {
		return nil
	}
	// [addr:]port
	host := ""
	portStr := v
	if idx := strings.LastIndex(v, ":"); idx >= 0 {
		host = v[:idx]
		portStr = v[idx+1:]
		_ = host
	}
	// port must be integer 0..65535
	n, err := strconv.Atoi(portStr)
	if err != nil || n < 0 || n > 65535 {
		// Original error reports the port portion if there was a colon? For "localhost:" it reported empty after colon, output "invalid listen port:" (port str)
		// For "abc" it reports whole string (same as portStr)
		return fmt.Errorf("invalid listen port: %s", portStr)
	}
	return nil
}

func validateInfo(v string) error {
	if v == "default" || v == "right" || v == "hidden" || v == "inline" || v == "inline-right" {
		return nil
	}
	if strings.HasPrefix(v, "inline:") || strings.HasPrefix(v, "inline-right:") {
		return nil
	}
	return fmt.Errorf("invalid info style (expected: default|right|hidden|inline[-right][:PREFIX])")
}

func validateMarginPadding(v string, kind string) error {
	parts := strings.Split(v, ",")
	if len(parts) < 1 || len(parts) > 4 {
		return fmt.Errorf("invalid %s: %s", kind, v)
	}
	for _, p := range parts {
		if strings.HasSuffix(p, "%") {
			numStr := p[:len(p)-1]
			f, err := strconv.ParseFloat(numStr, 64)
			if err != nil {
				return fmt.Errorf("not a valid number: %s", numStr)
			}
			if f < 0 {
				return fmt.Errorf("%s must be non-negative", kind)
			}
			if f > 49 {
				return fmt.Errorf("%s too large (max: 49%%)", kind)
			}
			continue
		}
		n, err := strconv.Atoi(p)
		if err != nil {
			// if float, still not valid integer
			return fmt.Errorf("not a valid integer: %s", p)
		}
		if n < 0 {
			return fmt.Errorf("%s must be non-negative", kind)
		}
	}
	return nil
}

func validateHistoryFile(v string) error {
