func (o *Options) setWalker(v string) error {
	if v == "" {
		return fmt.Errorf("at least one of 'file' or 'dir' should be specified")
	}
	parts := strings.Split(v, ",")
	file := false
	dir := false
	follow := false
	hidden := false
	for _, p := range parts {
		if p == "" { continue }
		switch strings.ToLower(p) {
		case "file": file = true
		case "dir": dir = true
		case "follow": follow = true
		case "hidden": hidden = true
		default:
			return fmt.Errorf("invalid walker option: %s", p)
		}
	}
	if !file && !dir {
		return fmt.Errorf("at least one of 'file' or 'dir' should be specified")
	}
	o.WalkerFile = file
	o.WalkerDir = dir
	o.WalkerFollow = follow
	o.WalkerHidden = hidden
	o.WalkerOpts = v
	return nil
}

