func validateColorSpec(v string) error {
	if v == "" {
		return nil
	}
	// split by comma and/or whitespace
	fields := strings.FieldsFunc(v, func(r rune) bool { return r == ',' || r == ' ' || r == '\t' || r == '\n' || r == '\r' })
	for _, entry := range fields {
		if entry == "" {
			continue
		}
		// base schemes alone
		lowerEntry := strings.ToLower(entry)
		if lowerEntry == "dark" || lowerEntry == "light" || lowerEntry == "base16" || lowerEntry == "16" || lowerEntry == "bw" {
			continue
		}
		parts := strings.Split(entry, ":")
		if len(parts) < 2 {
			return fmt.Errorf("invalid color specification: %s", entry)
		}
		name := parts[0]
		if name == "" {
			return fmt.Errorf("invalid color specification: %s", entry)
		}
		// Names might be like fg+ with space trimmed? Already fields
		// Check color name validity
		if _, ok := colorNames[name]; !ok || name == "current" {
			return fmt.Errorf("invalid color specification: %s", entry)
		}
		// For nth, all following parts must be attributes
		if name == "nth" {
			for _, p := range parts[1:] {
				if p == "" { continue }
				if !ansiAttrs[p] {
					return fmt.Errorf("only ANSI attributes are allowed for 'nth' (regular, bold, underline, reverse, dim, italic, strikethrough)")
				}
			}
			continue
		}
		// parts[1] is color (may be empty), rest attributes
		if len(parts) >= 2 {
			col := parts[1]
			if col != "" {
				if err := validateAnsiColor(col); err != nil {
					return fmt.Errorf("invalid color specification: %s", entry)
				}
			}
			for _, attr := range parts[2:] {
				if attr == "" { continue }
				if !ansiAttrs[attr] {
					return fmt.Errorf("invalid color specification: %s", entry)
				}
			}
		}
	}
	return nil
}

func validateAnsiColor(col string) error {
	if col == "" { return nil }
	// attribute alone as color? e. fg:italic, fg:bold  observed valid. If col is an attribute name, accept as attribute-only
	if ansiAttrs[col] {
		return nil
	}
	if col == "-1" {
		return nil
	}
	if strings.HasPrefix(col, "#") {
		hex := col[1:]
		if len(hex) != 6 {
			return fmt.Errorf("invalid")
		}
		for _, c := range hex {
			if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
				return fmt.Errorf("invalid")
			}
		}
		return nil
	}
	if ansiColorNames[strings.ToLower(col)] {
		// but bright-grey is invalid (in map? we have grey, bright-??)  -- check: gray/grey aliases are only for bright-black, not generic bright-grey
		if col == "bright-grey" || col == "bright-gray" {
			return fmt.Errorf("invalid")
		}
		return nil
	}
	// numeric 0-255
	if v, err := strconv.Atoi(col); err == nil {
		if v >= 0 && v <= 255 {
			return nil
		}
		return fmt.Errorf("invalid")
	}
	return fmt.Errorf("invalid")
}

// parseLong handles --name[=value]
func (o *Options) parseLong(arg string, args []string, idx int) (int, error) {
	// arg starts with --
	rest := arg[2:]
	name := rest
	value := ""
	hasValue := false
	if eq := strings.Index(rest, "="); eq >= 0 {
		name = rest[:eq]
		value = rest[eq+1:]
		hasValue = true
	}
	// helper closures
	nextRequired := func(requiredMsg string) (string, int, error) {
		if hasValue {
			return value, 1, nil
		}
		if idx+1 >= len(args) {
			return "", 1, fmt.Errorf("%s", requiredMsg)
		}
		return args[idx+1], 2, nil
	}
	nextOptional := func() (string, bool, int) {
		// returns value, present, consumed
		if hasValue {
			return value, true, 1
		}
		if idx+1 < len(args) {
			nxt := args[idx+1]
			if nxt == "" {
				return nxt, true, 2
			}
			r, _ := utf8.DecodeRuneInString(nxt)
			if r != '-' && r != '+' {
				return nxt, true, 2
			}
		}
		return "", false, 1
	}
