			n, err := strconv.Atoi(value)
			if err != nil { return 1, fmt.Errorf("not a valid integer: %s", value) }
			o.Sort = n != 0
		} else {
			o.Sort = true
		}
		return 1, nil
	case "multi":
		if hasValue {
			n, err := strconv.Atoi(value)
			if err != nil { return 1, fmt.Errorf("not a valid integer: %s", value) }
			o.MultiSet = true
			o.Multi = n
		} else {
			o.MultiSet = true
			o.Multi = -1
		}
		return 1, nil
	case "gap":
		if hasValue {
			n, err := strconv.Atoi(value)
			if err != nil { return 1, fmt.Errorf("not a valid integer: %s", value) }
			o.Gap = n
		} else {
