	borderOptions := map[string]*string{
		"border": &o.Border, "list-border": &o.ListBorder, "input-border": &o.InputBorder,
		"header-border": &o.HeaderBorder, "footer-border": &o.FooterBorder, "preview-border": nil, // special
	}
	if ptr, ok := borderOptions[name]; ok {
		if v, present, consumed := nextOptional(); present {
			if err := validateBorder(v); err != nil { return 1, err }
			if name == "preview-border" {
				// short for preview-window border
				o.PreviewOpts.Border = v; o.PreviewOpts.BorderSet = true
			} else {
				*ptr = v
				if name == "border" { o.BorderSet = true }
			}
