new=r'''// Match against zones built from display text
func (p *pattern) matchZones(zones []zone) (bool, int, int, int) {
	if p.empty || len(p.termSets) == 0 {
		return true, 0, 0, 0
	}
	// Precompute bonuses per zone
	zoneBonuses := make([][]int, len(zones))
	for i, z := range zones {
		zoneBonuses[i] = computeBonuses(z.text, p.sch)
	}
	total := 0
	overallBegin := -1
	overallEnd := -1
	for _, set := range p.termSets {
		bestScore := -1 << 30
		bestBegin := -1
		bestEnd := -1
		matched := false
		for _, t := range set {
			if t.inv {
				invMatched := false
				core := t.asNonInv()
				for zi, z := range zones {
					if ok, _, _, _ := p.matchTerm(core, z.text, zoneBonuses[zi]); ok {
						invMatched = true
						break
					}
				}
				if !invMatched {
					if !matched || 0 > bestScore {
						bestScore = 0
						bestBegin = -1
						bestEnd = -1
					}
					matched = true
				}
				continue
			}
			for zi, z := range zones {
				ok, sc, b, e := p.matchTerm(t, z.text, zoneBonuses[zi])
				if !ok {
					continue
				}
				gb := z.offset + b
				ge := z.offset + e
				if !matched || sc > bestScore {
					bestScore = sc
					bestBegin = gb
					bestEnd = ge
					matched = true
				}
			}
		}
		if !matched {
			return false, 0, 0, 0
		}
		total += bestScore
		if overallBegin == -1 && bestBegin != -1 {
			overallBegin = bestBegin
			overallEnd = bestEnd
		}
	}
	if overallBegin == -1 {
		overallBegin = 0
		overallEnd = 0
	}
	return true, total, overallBegin, overallEnd
}

func (p *pattern) match(text []rune) (bool, int, int, int) {
	return p.matchZones([]zone{{text: text, offset: 0}})
}

'''
