func trimmedLength(s string) int {
	// length after trimming trailing whitespace (space/tab etc)
	rs := []rune(s)
	end := len(rs)
	for end > 0 && unicode.IsSpace(rs[end-1]) {
		end--
	}
	return end
}

func criterionValue(opts *Options, crit string, r Result) int {
	display := r.Item.Display
	switch crit {
	case "length":
		return trimmedLength(display)
	case "begin":
		if r.Begin < 0 { return 0 }
		return r.Begin
	case "end":
		// closer to end preferred: trimmedLength - End
		return trimmedLength(display) - r.End
	case "chunk":
		if r.Begin < 0 || r.End < r.Begin {
			return trimmedLength(display)
		}
		rs := []rune(display)
		s := r.Begin
		if s > len(rs) { s = len(rs) }
		for s > 0 && !unicode.IsSpace(rs[s-1]) {
			s--
		}
		e := r.End
		if e < 0 { e = 0 }
		if e > len(rs) { e = len(rs) }
		for e < len(rs) && !unicode.IsSpace(rs[e]) {
			e++
		}
		return e - s
	case "pathname":
		rs := []rune(display)
		lastSlash := -1
		for i, ch := range rs {
			if ch == '/' { lastSlash = i }
		}
		if lastSlash == -1 {
			if r.Begin < 0 { return 0 }
			return r.Begin
		}
		if r.Begin > lastSlash {
			return r.Begin - (lastSlash + 1)
		}
		return 1 << 30
	case "index":
		return r.Item.Seq
	}
	return 0
}

