	if err := opts.parseArgs(cliArgs); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return 2
	}
	// Mode handling (last set wins already)
	switch opts.Mode {
	case "version":
		fmt.Print(versionText)
		return 0
	case "help":
		fmt.Print(helpText)
		return 0
	case "bash":
		fmt.Print(bashText)
		return 0
	case "zsh":
		fmt.Print(zshText)
		return 0
	case "fish":
		fmt.Print(fishText)
		return 0
	case "man":
		return runMan()
	}
	// NO_COLOR env handling
	if _, ok := os.LookupEnv("NO_COLOR"); ok {
		opts.NoColor = true
	}
	// Tmux mode: intercept later in interactive; for filter mode, tmux is ignored? Original: --tmux is ignored if not inside tmux, and filter mode exits before.
	// Determine if this is the inner tmux invocation (env flag)
	isTmuxInner := os.Getenv("__FZF_TMUX_INNER") == "1"
	if opts.Tmux && opts.Filter == nil && !isTmuxInner {
		// If inside tmux, launch popup via tmux; else ignore (original says ignored if not running inside tmux)
		if os.Getenv("TMUX") != "" {
			return runTmux(opts, cliArgs)
		}
		// not in tmux: ignore tmux option and proceed normally
	}
	// Load items
	items, headers, loadErr := loadItems(opts)
	if loadErr != nil {
		fmt.Fprintln(os.Stderr, loadErr.Error())
		return 2
	}
	_ = headers
	// Prepare results for filter / shortcuts
	if opts.Filter != nil {
		return runFilter(opts, items)
	}
	// Check select-1 / exit-0 shortcuts with --query
	// Build pattern from Query (if Disabled? shortcut still uses query pattern)
	pat := buildPattern(opts.Query, opts)
	results := filterItems(opts, items, pat)
	if opts.Select1 && len(results) == 1 {
		// act like accept
		out := buildInteractiveOutput(opts, [] *Item{results[0].Item}, "", opts.Query, nil)
		fmt.Print(out)
		return 0
	}
	if opts.Exit0 && len(results) == 0 {
		// print query/expect lines as interactive would on abort with no match? Observed: print-query prints query, expect prints blank line
		var lines []string
		if opts.PrintQuery {
			lines = append(lines, opts.Query)
		}
		if len(opts.Expect) > 0 {
			lines = append(lines, "")
		}
		if len(lines) > 0 {
			fmt.Print(strings.Join(lines, outputDelimiter(opts)) + outputDelimiter(opts))
		}
		return 1
	}
	// Interactive
	return runInteractive(opts, items, headers)
}

func outputDelimiter(opts *Options) string {
	if opts.Print0 {
		return "\x00"
	}
	return "\n"
}

func buildInteractiveOutput(opts *Options, selected []*Item, expectKey string, query string, printStrings []string) string {
	delim := outputDelimiter(opts)
	var lines []string
	if opts.PrintQuery {
		lines = append(lines, query)
	}
	if len(opts.Expect) > 0 {
		lines = append(lines, expectKey)
	}
	for _, s := range printStrings {
		lines = append(lines, s)
	}
	tok := makeOutputTokenizer(opts)
	for _, it := range selected {
		lines = append(lines, acceptOutput(opts, it, tok))
	}
	if len(lines) == 0 {
		return ""
	}
	// fzf prints each line with delimiter; if item contains newline, it's still followed by delimiter
	return strings.Join(lines, delim) + delim
}

func makeOutputTokenizer(opts *Options) *tokenizer {
	return makeTokenizer(opts.Delimiter)
}

func acceptOutput(opts *Options, it *Item, tok *tokenizer) string {
	if opts.AcceptNth != nil {
		return opts.AcceptNth.acceptTransform(it.Original, tok, it.OrigOrdinal)
	}
	return it.Original
}

func runFilter(opts *Options, items []*Item) int {
	pat := buildPattern(*opts.Filter, opts)
	results := filterItems(opts, items, pat)
	delim := outputDelimiter(opts)
	var out strings.Builder
	if opts.PrintQuery {
		out.WriteString(*opts.Filter)
		out.WriteString(delim)
	}
	tok := makeOutputTokenizer(opts)
	for _, r := range results {
		out.WriteString(acceptOutput(opts, r.Item, tok))
		out.WriteString(delim)
	}
	fmt.Print(out.String())
	if len(results) == 0 {
		return 1
	}
	return 0
}

func filterItems(opts *Options, items []*Item, pat *pattern) []Result {
	tok := makeTokenizer(opts.Delimiter)
	var results []Result
	for _, it := range items {
		zones := buildZones(it.Display, tok, opts.NthExpr, opts.HasNth)
		ok, score, begin, end := pat.matchZones(zones)
		if !ok {
			continue
		}
		results = append(results, Result{Item: it, Score: score, Begin: begin, End: end})
	}
	sortable := opts.Sort && pat.hasPositive && !pat.empty
	if sortable {
		sortResults(opts, results, items)
	}
	return results
}

func sortResults(opts *Options, results []Result, _ []*Item) {
	criteria := opts.Tiebreak
	sort.SliceStable(results, func(i, j int) bool {
		a := results[i]
		b := results[j]
		if a.Score != b.Score {
			return a.Score > b.Score
		}
		for _, crit := range criteria {
			va := criterionValue(opts, crit, a)
			vb := criterionValue(opts, crit, b)
			if va != vb {
				return va < vb
			}
		}
		// index implicit
		return a.Item.Seq < b.Item.Seq
	})
}

func trimmedLength(s string) int {
	// length after trimming trailing whitespace (space/tab etc)
	rs := []rune(s)
	end := len(rs)
	for end > 0 && unicode.IsSpace(rs[end-1]) {
		end--
	}
	return end
}

func criterionValue(opts *Options, crit string, r Result) int {
	display := r.Item.Display
	switch crit {
	case "length":
		return trimmedLength(display)
	case "begin":
		if r.Begin < 0 { return 0 }
		return r.Begin
	case "end":
		// closer to end preferred: trimmedLength - End
		return trimmedLength(display) - r.End
	case "chunk":
		if r.Begin < 0 || r.End < r.Begin {
			return trimmedLength(display)
		}
		rs := []rune(display)
		s := r.Begin
		if s > len(rs) { s = len(rs) }
		for s > 0 && !unicode.IsSpace(rs[s-1]) {
			s--
		}
		e := r.End
		if e < 0 { e = 0 }
		if e > len(rs) { e = len(rs) }
		for e < len(rs) && !unicode.IsSpace(rs[e]) {
			e++
		}
		return e - s
	case "pathname":
		rs := []rune(display)
		lastSlash := -1
		for i, ch := range rs {
			if ch == '/' { lastSlash = i }
		}
		if lastSlash == -1 {
			if r.Begin < 0 { return 0 }
			return r.Begin
		}
		if r.Begin > lastSlash {
			return r.Begin - (lastSlash + 1)
		}
		return 1 << 30
	case "index":
		return r.Item.Seq
	}
	return 0
}

func runMan() int {
	tmpfile, err := os.CreateTemp("", "fzf-temp-")
	if err != nil {
		fmt.Print(manText)
		return 0
	}
	name := tmpfile.Name()
	defer os.Remove(name)
	if _, err := tmpfile.WriteString(manText); err != nil {
		tmpfile.Close()
		fmt.Print(manText)
		return 0
	}
	tmpfile.Close()
	// set MANPAGER / PAGER to cat if not present
	env := os.Environ()
	if _, ok := os.LookupEnv("MANPAGER"); !ok {
		env = append(env, "MANPAGER=cat")
	}
	if _, ok := os.LookupEnv("PAGER"); !ok {
		env = append(env, "PAGER=cat")
	}
	cmd := exec.Command("man", name)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Env = env
	if err := cmd.Run(); err != nil {
		fmt.Print(manText)
		return 0
	}
	return 0
}

// Input loading

func isStdinTTY() bool {
	fi, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func findStartReload(opts *Options) (string, bool) {
	for _, b := range opts.Binds {
		isStart := false
		for _, k := range b.Keys {
			if strings.ToLower(k) == "start" { isStart = true }
		}
		if !isStart { continue }
		for _, a := range b.Actions {
			if a.Name == "reload" || a.Name == "reload-sync" {
				return a.Arg, true
			}
		}
	}
	return "", false
}

func loadItems(opts *Options) ([]*Item, []string, error) {
	var rawLines []string
	// If scheme not explicitly set, and starting walker/default command, fzf would choose path scheme.
	// We determine source type here for later scheme adjustment? This affects filter matching when input is TTY.
	// Original rule: scheme=path when input is TTY, starting walker or $FZF_DEFAULT_COMMAND, and no reload/transform on start.
	// If scheme not set (user didn't specify --scheme), adjust opts.Scheme before building pattern.
	// Our callers build pattern after loadItems, so adjusting here works.
	adjustSchemeForTTY(opts)
	if cmdStr, ok := findStartReload(opts); ok {
		lines, err := runShellCommandForInput(opts, cmdStr)
		if err != nil {
			// If command fails, lines may still be partial; fzf ignores?
			rawLines = lines
		} else {
			rawLines = lines
		}
	} else if isStdinTTY() {
		if defCmd := os.Getenv("FZF_DEFAULT_COMMAND"); defCmd != "" {
			lines, _ := runShellCommandForInput(opts, defCmd)
			rawLines = lines
		} else {
			lines := walkItems(opts)
			rawLines = lines
		}
	} else {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return nil, nil, err
		}
		rawLines = splitInput(string(data), opts.Read0)
	}
	// Separate header lines
	var headers []string
	rest := rawLines
	if opts.HeaderLines > 0 {
		if opts.HeaderLines >= len(rawLines) {
			headers = rawLines
			rest = nil
		} else {
			headers = rawLines[:opts.HeaderLines]
			rest = rawLines[opts.HeaderLines:]
		}
	}
	// Create items with orig ordinals
	var items []*Item
	for idx, line := range rest {
		text := line
		if opts.Ansi {
			text = stripAnsi(text)
		}
		it := &Item{Original: text, OrigOrdinal: idx}
		items = append(items, it)
	}
	// Tail: keep last N
	if opts.Tail > 0 && len(items) > opts.Tail {
		items = items[len(items)-opts.Tail:]
	}
	// Tac: reverse order for sequence
	if opts.Tac {
		for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
			items[i], items[j] = items[j], items[i]
		}
	}
	// Assign sequence and display
	tok := makeTokenizer(opts.Delimiter)
	for seq, it := range items {
		it.Seq = seq
		display := it.Original
		if opts.WithNth != nil {
			display = opts.WithNth.transform(display, tok, it.OrigOrdinal)
		}
		it.Display = display
	}
	// Headers for display: transform with-nth as original does (?) Headers when WithNth set, headerLines are transformed
	// Keep headers as strings; transform later in TUI as needed using Original lines (after ANSI)
	var headerTexts []string
	for _, h := range headers {
		text := h
		if opts.Ansi {
			text = stripAnsi(text)
		}
		if opts.WithNth != nil {
			// ordinals for header lines? They are not items; fzf uses ... Use 0? Actually header lines transformation uses their original index among all lines? For display not critical.
			text = opts.WithNth.transform(text, tok, 0)
		}
		headerTexts = append(headerTexts, text)
	}
	return items, headerTexts, nil
}

func adjustSchemeForTTY(opts *Options) {
	if opts.schemeSet {
		return
	}
	if opts.Filter != nil && !isStdinTTY() {
		// Filter with piped stdin: scheme default (already)
		return
	}
	if isStdinTTY() {
		// check start reload/transform
		for _, b := range opts.Binds {
			for _, k := range b.Keys {
				if strings.ToLower(k) == "start" {
					for _, a := range b.Actions {
						if a.Name == "reload" || a.Name == "reload-sync" || strings.HasPrefix(a.Name, "transform") || strings.HasPrefix(a.Name, "bg-transform") {
							return
						}
					}
				}
			}
		}
		// walker or default command will be used
		opts.Scheme = "path"
		opts.Tiebreak = getScheme("path").tiebreak
	}
	// Also, if start reload exists, scheme stays default (not path) per man. Already default.
	if _, ok := findStartReload(opts); ok {
		// If scheme would have been set by ... keep default.
		// Ensure that if we earlier... This function is called before source selection; don't change.
	}
}

func splitInput(data string, read0 bool) []string {
	if data == "" {
		return nil
	}
	delim := "\n"
	if read0 {
		delim = "\x00"
	}
	var lines []string
	start := 0
	for {
		idx := strings.Index(data[start:], delim)
		if idx < 0 {
			// final partial
			if start < len(data) {
				lines = append(lines, data[start:])
			}
			break
		}
		lines = append(lines, data[start:start+idx])
		start = start + idx + len(delim)
		if start >= len(data) {
			break
		}
	}
	return lines
}

func shellCommandParts(opts *Options, command string) (string, []string) {
	// returns executable and args to precede command string
	if opts.WithShell != "" {
		// parse with-sell as shell words
		parts, err := splitOptsString(opts.WithShell)
		if err == nil && len(parts) > 0 {
			return parts[0], append(parts[1:], command)
		}
	}
	if sh := os.Getenv("SHELL"); sh != "" {
		return sh, []string{"-c", command}
	}
	return "sh", []string{"-c", command}
}

func runShellCommandForInput(opts *Options, command string) ([]string, error) {
	exe, args := shellCommandParts(opts, command)
	cmd := exec.Command(exe, args...)
	// env for child: inherit plus FZF variables (basic)
	cmd.Env = buildChildEnv(opts, "", "")
	var out strings.Builder
	cmd.Stdout = &out
	cmd.Stderr = os.Stderr
	// stdin from tty? For default command, stdin is??? Use nil
	err := cmd.Run()
	data := out.String()
	if opts.Read0 {
		return splitInput(data, true), err
	}
	return splitInput(data, false), err
}

func buildChildEnv(opts *Options, current string, query string) []string {
	env := os.Environ()
	// FZF_DEFAULT_COMMAND etc are already in env if set; add placeholders variables used by preview/execute child processes
	// Caller may add specific ones.
	_ = current
	_ = query
	return env
}

func walkItems(opts *Options) []string {
	roots := opts.WalkerRoots
	if len(roots) == 0 {
		roots = []string{"."}
	}
	skip := map[string]bool{}
	if opts.WalkerSkip != "" {
		for _, s := range strings.Split(opts.WalkerSkip, ",") {
			skip[strings.TrimSpace(s)] = true
		}
	}
	var out []string
	visitedDirs := map[string]bool{}
	for _, root := range roots {
		rootClean := filepath.Clean(root)
		info, err := os.Stat(rootClean)
		if err != nil {
			continue
		}
		if !info.IsDir() {
			// file root
			if opts.WalkerFile {
				// Output as given? Original used Clean? "a.txt" gave a.txt, "/tmp/.../b.txt" - if root is a file like sub/../a.txt, clean it
				out = append(out, rootClean)
			} else if opts.WalkerDir && info.IsDir() {
				// not reached
			}
			continue
		}
		// root is dir: walk it
		walkDir(rootClean, opts, skip, &out, visitedDirs)
	}
	return out
}

func walkDir(dir string, opts *Options, skip map[string]bool, out *[]string, visited map[string]bool) {
	// Prevent cycles for followed symlinks: track canonical path of directories visited via this call stack? For simplicity, visited global prevents re-walking same canonical dir twice only when following symlinks?
	// Real dirs that are repeated via different roots should be walked again? Use a stack approach: pass visited as set of canonical dirs currently in recursion? Simpler: don't use global visited for real dirs, only check ancestors.
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	// os.ReadDir returns sorted by filename
	for _, entry := range entries {
		name := entry.Name()
		path := filepath.Join(dir, name)
		isHidden := strings.HasPrefix(name, ".")
		// Determine type
		info, err := entry.Info() // follows? DirEntry.Info reports the file info of the file (for symlink, it's target? Actually Info returns info about target? doc: Info returns FileInfo for the file or subdirectory described by entry, if symlink, it is info of link itself? Go: Info returns the FileInfo for the file; if symlink, returns info about target? Checking: os.DirEntry.Info: "returns the FileInfo for the file or subdirectory described by the entry. The returned FileInfo may be from the time of the original directory read or from a later time. If the file has been removed or renamed since the directory read, Info may return an error. If the entry denotes a symbolic link, the FileInfo is information about the target file."
		// So for symlinks, Info will be target.
		var isDir bool
		var isSymlink bool
		if entry.Type()&os.ModeSymlink != 0 {
			isSymlink = true
		}
		if err == nil && info.IsDir() {
			isDir = true
		}
		if isDir {
			if skip[name] {
				continue
			}
			if isHidden && !opts.WalkerHidden {
				continue
			}
			if isSymlink && !opts.WalkerFollow {
				continue
			}
			if opts.WalkerDir {
				*out = append(*out, path+"/")
			}
			// Recurse, with cycle protection using canonical path in visited set along recursion? Use a simple check: if this canonical dir already visited globally and is symlink, skip recursing to avoid loops.
			if isSymlink {
				if canon, err := filepath.EvalSymlinks(path); err == nil {
					if visited[canon] {
						continue
					}
					visited[canon] = true
					walkDir(path, opts, skip, out, visited)
					delete(visited, canon)
				} else {
					walkDir(path, opts, skip, out, visited)
				}
			} else {
				walkDir(path, opts, skip, out, visited)
			}
			continue
		}
		// Not a directory
		if isSymlink {
			// symlink to file (info is target file, not dir)
			if err != nil {
				continue
			}
			if isHidden && !opts.WalkerHidden {
				continue
			}
			if opts.WalkerFile {
				*out = append(*out, path)
			}
			continue
		}
		// Regular or other
		if isHidden && !opts.WalkerHidden {
			continue
		}
		if opts.WalkerFile {
			// Only include regular files? Include fifos etc? Include if not dir
			*out = append(*out, path)
		}
	}
}

