new_fb=r'''func (p *pattern) fuzzyForwardBackward(t term, text []rune) (int, int, []int, bool) {
	// forward greedy for first completion
	m := len(t.text)
	n := len(text)
	j := 0
	endFirst := -1
	var forwardPos []int
	for i := 0; i < n && j < m; i++ {
		if charEqual(t.text[j], text[i], t.caseSensitive, p.literal) {
			forwardPos = append(forwardPos, i)
			j++
			if j == m {
				endFirst = i + 1
				break
			}
		}
	}
	if j < m {
		return 0, 0, nil, false
	}
	// backward from endFirst to tighten begin
	positions := make([]int, m)
	j = m - 1
	begin := -1
	for i := endFirst - 1; i >= 0 && j >= 0; i-- {
		if charEqual(t.text[j], text[i], t.caseSensitive, p.literal) {
			positions[j] = i
			j--
			if j < 0 {
				begin = i
				break
			}
		}
	}
	if begin < 0 {
		return 0, 0, nil, false
	}
	// backward over whole text to find last match end
	j = m - 1
	endLast := -1
	for i := n - 1; i >= 0 && j >= 0; i-- {
		if charEqual(t.text[j], text[i], t.caseSensitive, p.literal) {
			if j == m-1 {
				endLast = i + 1
			}
			j--
			if j < 0 {
				break
			}
		}
	}
	if endLast < 0 {
		endLast = endFirst
	}
	_ = forwardPos
	return begin, endLast, positions, true
}

'''
