import subprocess, os, random, sys
def run(exe,args,inp):
    e={k:v for k,v in os.environ.items() if not k.startswith("FZF_")}
    p=subprocess.run([exe]+args, input=inp.encode(), capture_output=True, env=e)
    return p.stdout,p.stderr,p.returncode

def differs(args,items):
    inp="\n".join(items)+"\n"
    return run("./executable",args,inp)!=run("/tmp/myfzf",args,inp)

def build_items():
    random.seed(42)
