    words=["foo","bar","baz","qux","hello","world","a","ab","abc","x","y","z","file.txt","dir/file","a-b","a_b","Test","FOO"]
    items=[]
    for _ in range(100):
        items.append(" ".join(random.choice(words) for _ in range(random.randint(1,4))))
    return items

items=build_items()
for args in [["--filter=a","--nth=1,3"],["--filter=file","-e"]]:
