            # remove one occurrence
            trial=cur.copy(); trial.remove(x)
            if differs(args,trial):
                cur=trial; changed=True; break
    print("minimal",cur)
    inp="\n".join(cur)+"\n"
    a=run("./executable",args,inp); b=run("/tmp/myfzf",args,inp)
    print("orig",a); print("mine",b)
