def run(exe,args,inp):
    e={k:v for k,v in os.environ.items() if not k.startswith("FZF_")}
    p=subprocess.run([exe]+args, input=inp.encode(), capture_output=True, env=e)
    return p.stdout,p.stderr,p.returncode
random.seed(1)
alph="abcXYZ _-/.,:;|"
items=[]
for _ in range(200):
    n=random.randint(0,12)
    items.append("".join(random.choice(alph) for _ in range(n)))

def differs(args,cur):
    inp="\n".join(cur)+"\n"
    return run("./executable",args,inp)!=run("/tmp/myfzf",args,inp)

def minimize(args):
    cur=items[:]
    print("start diff",differs(args,cur))
    changed=True
    while changed:
        changed=False
        for x in list(cur):
            trial=cur.copy(); trial.remove(x)
            if differs(args,trial):
                cur=trial; changed=True; break
    print("minimal",cur)
    inp="\n".join(cur)+"\n"
    print("orig",run("./executable",args,inp))
    print("mine",run("/tmp/myfzf",args,inp))

for args in [["--filter=c"],["--filter=c","--tiebreak=begin"],["--filter=y","--exact","--tiebreak=end"]]:
    print("CASE",args)
    minimize(args)
PY
