{"command":"cat > /tmp/fix_single.py << 'PY'
import pathlib
p=pathlib.Path("pattern.go")
s=p.read_text()
marker="""func (p *pattern) fuzzyV2Internal(t term, text []rune, bonuses []int) (bool, int, int, int, []int) {"""
new=marker+"""
	// Special case for a single-character pattern in forward mode:
	// choose the first occurrence at a word boundary (preceded by a non-word
	// character or at the start); if there is no such occurrence, choose the
	// first occurrence. This mirrors the observed behaviour of the original
	// for one-character fuzzy terms, which differs from the general DP that
	// would pick the highest-scoring occurrence anywhere in the span.
	if len(t.text) == 1 && !p.backward {
		first := -1
		for i, r := range text {
			_ = r
			if !charEqual(t.text[0], text[i], t.caseSensitive, p.literal) {
				continue
			}
			if first < 0 {
				first = i
			}
			if i == 0 || !isWordRune(text[i-1]) {
				sc := scoreMatch + bonuses[i]*bonusFirstCharMultiplier
				return true, sc, i, i + 1, []int{i}
			}
		}
		if first >= 0 {
			sc := scoreMatch + bonuses[first]*bonusFirstCharMultiplier
			return true, sc, first, first + 1, []int{first}
		}
		return false, 0, 0, 0, nil
	}
"""
if marker not in s:
    print("marker not found")
else:
    s=s.replace(marker,new,1)
p.write_text(s)
PY
