go build -o /tmp/myfzf . 2>&1 | head
python3 /tmp/minimize1.py 2>&1 | tail -20
python3 /tmp/test_filter.py 2>&1 | grep -c DIFF; python3 /tmp/fuzz2.py 2>&1 | tail -1"}

