{"command":"cat > /tmp/fix_backward3.py << 'PY'
import pathlib
p=pathlib.Path("pattern.go")
s=p.read_text()

# FuzzyV2 wrapper replacement
start=s.find("func (p *pattern) fuzzyV2(t term, text []rune, bonuses []int) (bool, int, int, int, int, int) {")
end=s.find("func (p *pattern) fuzzyV2Internal")
assert start!=-1 and end!=-1
new=r'''func (p *pattern) fuzzyV2(t term, text []rune, bonuses []int) (bool, int, int, int, int, int) {
	if p.backward {
		revText := reverseRunes(text)
		revTerm := t
		revTerm.text = reverseRunes(t.text)
		revBonuses := computeBonuses(revText, p.sch)
		oldBackward := p.backward
		p.backward = false
		ok, _, _, _, revPositions := p.fuzzyV2Internal(revTerm, revText, revBonuses)
		p.backward = oldBackward
		if !ok {
			return false, 0, 0, 0, 0, 0
		}
		origPos := mapRevPositions(revPositions, len(text))
		sc := scoreAlignment(origPos, bonuses)
		return true, sc, origPos[0], origPos[len(origPos)-1] + 1, origPos[0], origPos[len(origPos)-1] + 1
	}
	ok, sc, spanB, spanE, positions := p.fuzzyV2Internal(t, text, bonuses)
	if !ok {
		return false, 0, 0, 0, 0, 0
	}
	if len(positions) == 0 {
		return true, sc, spanB, spanE, spanB, spanE
	}
	return true, sc, spanB, spanE, positions[0], positions[len(positions)-1] + 1
}

'''
s=s[:start]+new+s[end:]

# Exact backward: replace the backward integrated best selection with last occurrence
# Remove the comment line and make selection conditional
s=s.replace("""	// backward mode is handled by the best-score selection below with latest tie preference
	bestScore := -1 << 30""","""	if p.backward {
		for sidx := n - m; sidx >= 0; sidx-- {
			ok := true
			for i := 0; i < m; i++ {
				if !charEqual(t.text[i], text[sidx+i], t.caseSensitive, p.literal) {
					ok = false
					break
				}
			}
			if !ok {
				continue
			}
			positions := make([]int, m)
			for i := range positions { positions[i] = sidx + i }
			sc := scoreAlignment(positions, bonuses)
			return true, sc, sidx, sidx + m, sidx, sidx + m
		}
		return false, 0, 0, 0, 0, 0
	}
	bestScore := -1 << 30""")
# In forward exact selection, the condition currently includes backward tie; leave as is (backward branch returns earlier)

# Boundary backward: replace candidate selection with last-trailing-boundary logic
s=s.replace("""	chosen := cands[0]
	for _, c := range cands {
		if c.score > chosen.score || (p.backward && c.score == chosen.score) {
			chosen = c
		}
	}""","""	chosen := cands[0]
	if p.backward {
		// From the right, choose the first occurrence whose following
		// character is a non-word (or the end); otherwise the last occurrence.
		chosen = cands[len(cands)-1]
		for idx := len(cands) - 1; idx >= 0; idx-- {
			c := cands[idx]
			post := neighborCategory(text, c.start+m)
			if post != catWord {
				chosen = c
				break
			}
		}
		return true, chosen.score, chosen.start, chosen.start + m, chosen.start, chosen.start + m
	}
	for _, c := range cands {
		if c.score > chosen.score {
			chosen = c
		}
	}""")
p.write_text(s)
PY
